// EmpathyGym Trainer Data — автогенерация из TrainerData.kt (build_content.py)
// НЕ редактировать вручную.
window.TRAINER_DATA={"ru":[{"id":"validate","tt":"Валидируй","ds":"Выбери валидирующий ответ","sm":"c","ins":["Прочитай ситуацию","Выбери валидирующий ответ из четырёх","Неточный ответ покажет, почему он не подходит"],"dt":[{"s":"Лера пишет в чат:\n«Настя опять отменила наши планы. Третий раз за месяц. Даже не извинилась толком, просто \"ой, не могу\". Я уже даже не знаю, зачем что-то планировать».","o":[{"t":"Лер, три раза подряд — это реально обидно. И то, что даже без извинений — ещё неприятнее.","e":"Называет чувство (обида), отражает ситуацию, не советует.","g":"Валидация","ok":1},{"t":"Может, у Насти реально завал на работе? Попробуй не обижаться, она же не специально.","e":"Оправдывает Настю, просит «не обижаться» — запрещает чувство.","g":"Запрет чувства"},{"t":"Слушай, ну если она так делает, просто перестань её звать. Зачем тебе такая подруга?","e":"Непрошеный совет — решает за Леру вместо поддержки.","g":"Совет"},{"t":"У меня тоже так было с Олей, помнишь? Все так делают иногда, просто забей.","e":"Переключает на себя, обесценивает через «все так делают».","g":"Обесценивание"}]},{"s":"Соня (6 лет) пришла из сада, плачет:\n«Маша сказала, что не будет со мной дружить! И все пошли играть с ней, а я одна сидела!»","o":[{"t":"Ну Сонечка, не плачь! Маша завтра забудет, и вы снова будете играть.","e":"Отрицает чувство, обещает то, что не может гарантировать.","g":"Обесценивание"},{"t":"А ты у Маши спросила, почему? Может, ты что-нибудь сделала, и она обиделась на тебя?","e":"Перекладывает вину на ребёнка, заставляет оправдываться.","g":"Обвинение"},{"t":"Тебе обидно, что Маша так сказала. И одной сидеть, когда все играют — это грустно, я понимаю.","e":"Называет оба чувства (обида + грусть), отражает ситуацию.","g":"Валидация","ok":1},{"t":"Ничего страшного, солнышко! У тебя полно друзей. Завтра поиграешь с Полиной, всё будет хорошо!","e":"Минимизирует боль, переключает на позитив.","g":"Отвлечение"}]},{"s":"Даша после собеседования:\n«Третий отказ подряд. Готовилась к каждому: читала про компанию, делала тестовые. А мне даже фидбэк не дают, просто \"вы нам не подходите\". Начинаю думать, что со мной что-то не так».","o":[{"t":"Три это мало, серьёзно. У меня было 15 отказов, когда искала. Просто продолжай, твоя вакансия найдётся!","e":"Сравнивает с собой, минимизирует боль через статистику.","g":"Обесценивание"},{"t":"Может, стоит попросить фидбэк? Или показать резюме HR-специалисту? Так поймёшь, что можно улучшить.","e":"Перескакивает к решению, не признаёт чувство.","g":"Совет"},{"t":"С тобой всё в порядке, Даш. Рынок сложный, конкуренция бешеная. Ты точно справишься, я в тебя верю!","e":"Отрицает сомнение вместо признания боли.","g":"Бодрящее отрицание"},{"t":"Подожди, три раза подряд и даже не сказали, что не так? Ну это вообще...","e":"Эхо с удивлением. Незаконченная фраза показывает, что слов не хватает.","g":"Валидация","ok":1}]},{"s":"Карина тихо:\n«Мурка умерла вчера. 14 лет вместе. На работе все: \"Это же кошка, заведи другую\". Как будто она вещь, которую можно заменить».","o":[{"t":"Мне жаль, Карин. Но знаешь, может правда стоит котёнка завести? Это помогает пережить потерю.","e":"Повторяет обесценивание коллег в мягкой форме.","g":"Совет"},{"t":"Понимаю тебя, у меня тоже собака умирала. Время лечит, поверь, через месяц станет полегче.","e":"Переключает на себя, обещает без основания.","g":"Перетягивание"},{"t":"14 лет — это огромная часть жизни. Конечно, боль от этой потери очень глубокая.","e":"Признаёт масштаб потери, легитимизирует глубину боли.","g":"Валидация","ok":1},{"t":"Они не со зла, просто не знают, что сказать. Попробуй не обижаться на них, у них, наверное, никогда не было питомцев.","e":"Оправдывает тех, кто обесценил, просит «не обижаться».","g":"Защита обидчиков"}]},{"s":"Настя из Берлина:\n«Полгода тут, а друзей ноль. На работе все вежливые, но дальше \"Hi, how are you\" — не заходит. По вечерам сижу одна, смотрю русские сериалы и плачу».","o":[{"t":"Полгода это мало, дай время. Запишись куда-нибудь, на йогу или курсы, там точно кого-нибудь найдёшь.","e":"Минимизирует срок, даёт совет вместо поддержки.","g":"Совет"},{"t":"Сидеть одной каждый вечер в чужой стране — это пронзительное одиночество. И плакать от этого — нормально.","e":"Называет чувство, нормализует реакцию, не советует.","g":"Валидация","ok":1},{"t":"Но ты же сама хотела переехать, помнишь? Вспомни, ради чего это затевалось, и держись!","e":"Напоминает о выборе как аргумент против чувств.","g":"Упрёк"},{"t":"Пробовала русскоязычные группы? В Берлине полно наших, в телеграме куча чатов. Там быстро находишь своих.","e":"Решает проблему вместо признания боли.","g":"Совет"}]},{"s":"Арина рассказывает:\n«Сказала Саше, что обидно, не позвонил, когда болела. А он: \"Ты опять драматизируешь, я был занят, хватит сцены устраивать\"».","o":[{"t":"Может, он реально был загружен? Мужчины иначе заботу проявляют. Попробуй объяснить ему поспокойнее.","e":"Оправдывает Сашу, просит Арину измениться.","g":"Защита обидчика"},{"t":"Вам надо серьёзно поговорить, когда оба остынете. Скажи, как тебя ранили эти слова. Он должен услышать.","e":"Перескакивает к плану действий.","g":"Совет"},{"t":"Это звоночек, Арин. Если сейчас так реагирует, дальше будет хуже. Задумайся, нужен ли тебе такой человек.","e":"Оценивает отношения вместо признания чувств.","g":"Приговор"},{"t":"Подожди — ты пришла сказать, что тебе обидно, а он это назвал «сценой»? Это же двойной удар — сначала не позвонил, потом ещё и обесценил.","e":"Называет механизм (двойной удар). Не терапевтическим тоном, а через пересказ.","g":"Валидация","ok":1}]},{"s":"Марина шёпотом:\n«Лучшую подругу повысили. Я улыбалась, поздравляла. Дома рыдала. Не потому что не рада. А потому что завидно. И тошно от себя, какой я после этого человек».","o":[{"t":"Зависть нормально, все завидуют. Главное, ты рада за неё, и это говорит о тебе хорошее.","e":"Минимизирует через «все так». Фокус на позитиве вместо боли.","g":"Обесценивание"},{"t":"Радоваться и завидовать одновременно — не делает тебя плохой. Это делает тебя живым человеком.","e":"Признаёт оба чувства одновременно, снимает стыд.","g":"Валидация","ok":1},{"t":"Может, зависть сигнал, что тебе тоже пора расти? Используй её как мотивацию, это здоровый подход.","e":"Переводит чувство в задачу, игнорирует стыд.","g":"Рефрейминг"},{"t":"Если так завидно, стоит разобраться, чего тебе самой не хватает. Психолог мог бы помочь с этим.","e":"Отправляет к специалисту вместо признания.","g":"Совет"}]},{"s":"Олег:\n«Прочитал переписку Маши с бывшим. Знаю, нельзя было лезть. Но там \"скучаю по нашим поездкам\", смайлики. Не могу на неё смотреть, а сказать не могу, сам виноват, что полез».","o":[{"t":"Ты сделал паршивую вещь — и знаешь это. Но увидеть «скучаю» — реально больно. Одно не отменяет другое.","e":"Не оправдывает, но валидирует чувство. Признаёт оба факта.","g":"Валидация","ok":1},{"t":"А что ты хотел, лазая в чужой телефон? Сам нарушил доверие. Поговори с ней честно, хватит молчать.","e":"Добивает виной, даёт совет.","g":"Упрёк + совет"},{"t":"Многие дружат с бывшими, переписка это нормально. Не факт, что там серьёзное, не накручивай себя.","e":"Обесценивает увиденное, просит «не накручивать».","g":"Минимизация"},{"t":"Если скучает по бывшему, может, ей с тобой чего-то не хватает. Вам пора серьёзно поговорить об этом.","e":"Домысливает мотивы, уводит от чувства Олега.","g":"Интерпретация"}]},{"s":"Таня:\n«Бабушка в больнице. Мама ездит каждый день, а я не могу. Работа, дети, нет сил. Бабушка: \"Всё хорошо, не приезжай\". Но я знаю, ей плохо. И знаю, что потом буду жалеть».","o":[{"t":"Найди хоть один день, Тань. Потом будешь жалеть. Серьёзно, потом себе не простишь, я знаю.","e":"Усиливает чувство вины вместо поддержки.","g":"Давление виной"},{"t":"Ты делаешь что можешь: звонишь, думаешь о ней. Не вини себя, бабушка тебя точно поймёт.","e":"Отрицает вину вместо признания ловушки.","g":"Бодрящее утешение"},{"t":"Приехать — нет сил. Не приехать — сожрёт вина. И оба варианта не очень.","e":"Называет ловушку — пересказывает реальность без интерпретации.","g":"Валидация","ok":1},{"t":"Организуй сиделку, или попроси маму записать видеозвонок. Хоть как-то «побудешь» рядом с ней.","e":"Решает проблему вместо признания.","g":"Совет"}]},{"s":"Руслан:\n«Получил повышение. Все поздравляют, а я жду, когда разоблачат. Макс работает лучше, Лена умнее. Мне повезло. Или руководство ошиблось».","o":[{"t":"Тебя повысили заслуженно! Ты крутой специалист, хватит себя принижать, порадуйся наконец!","e":"Отрицает переживание, требует радости.","g":"Бодрящее отрицание"},{"t":"Это синдром самозванца, многие через это проходят. Почитай — когда поймёшь паттерн, станет легче.","e":"Ставит ярлык вместо признания чувства.","g":"Диагноз"},{"t":"Раз повысили, значит, видят потенциал. Не тебе решать, кто лучше, руководство уже решило.","e":"Аргументирует вместо поддержки.","g":"Логика"},{"t":"Повысили — а ты сидишь и ждёшь, когда скажут «ошибочка вышла»? Руслан, ну это же мучительно.","e":"Эхо с удивлением. Возвращает его слова, добавляет только одно — «мучительно».","g":"Валидация","ok":1}]},{"s":"Саша после ссоры:\n«Опять сорвался из-за ерунды. Жена просто спросила про ужин, а я начал орать. Какой же мудак. Она не заслуживает такого».","o":[{"t":"Сорвался — и мне хреново от этого. Значит, мне не всё равно. Я не мудак — я устал и не справился. Разные вещи.","e":"Разделяет поступок и личность. «Хреново» = мне важны отношения.","g":"Самовалидация","ok":1},{"t":"Я мудак и всегда буду. Она уйдёт, и правильно сделает. Я только порчу всё, к чему прикасаюсь.","e":"Катастрофизация, приговор вместо разбора.","g":"Самобичевание"},{"t":"Все иногда орут, ничего такого. Она привыкла. Завтра куплю цветы, и проехали, не трагедия.","e":"Обесценивает и свою вину, и чувства жены.","g":"Минимизация"},{"t":"Надо научиться контролировать эмоции. Запишусь к психологу, начну медитировать, стану лучше.","e":"Перескакивает к решению, минуя признание.","g":"План побега"}]},{"s":"Тимофей:\n«Макс выложил: \"Ушёл с работы, стартап, первый миллион за полгода\". 500 лайков. А я знаю, что он в долгах, жена ушла. Но все пишут \"красавчик\". И мне противно и завидно одновременно».","o":[{"t":"Ты же знаешь правду! Зачем завидовать? У Макса всё плохо на самом деле. Ты в лучшей позиции.","e":"Зависть иррациональна, «знание правды» не отменяет чувство.","g":"Рационализация"},{"t":"Удали соцсети, серьёзно. Без них намного лучше. Вся показуха, чистый яд для психики, проверено.","e":"Непрошеный совет вместо признания.","g":"Совет"},{"t":"Знаешь, что это враньё — и всё равно завидуешь. Плюс бесит, что все ведутся. И то и другое — и непонятно, на кого злишься больше — на него, на всех или на себя.","e":"Называет противоречие, не пытается разрешить.","g":"Валидация","ok":1},{"t":"Макс это Макс, ты это ты. Не сравнивай. Своя дорога ничем не хуже, у каждого свой путь.","e":"Запрещает сравнение, которое уже произошло.","g":"Клише"}]},{"s":"Миша (8 лет) перед школой:\n«Не пойду. Вадик опять будет обзываться. Вчера при всех сказал, что я тупой. Учительница не слышала.»\n(Кулаки сжаты, глаза мокрые.)","o":[{"t":"Поговорю с учительницей, не переживай. Вадик больше так не будет делать, обещаю тебе, всё будет хорошо.","e":"Обещает то, что не может гарантировать.","g":"Ложное обещание"},{"t":"Ты злишься и тебе больно — он сделал это при всех, и никто не помог. Это нечестно.","e":"Называет оба чувства (злость + боль), признаёт несправедливость.","g":"Валидация","ok":1},{"t":"Скажи ему что-нибудь в ответ! Не давай обижать. Ты можешь за себя постоять, давай, ты же мужик!","e":"Требует бороться, игнорирует боль.","g":"Давление"},{"t":"Вадик сам несчастный, счастливые так не делают. Не обращай внимания, он просто выпендривается.","e":"Объясняет чужое поведение вместо признания чувств Миши.","g":"Рефрейминг"}]},{"s":"Гриша:\n«Панические атаки. Сердце колотится, руки трясутся, кажется, умираю. Маме сказал, а она: \"Это от телефона, погуляй\". Друзья: \"Ты много думаешь\". Как будто выдумываю».","o":[{"t":"А ты был у врача? Панические атаки лечатся. Терапия, иногда таблетки, станет значительно легче.","e":"Перескакивает к решению.","g":"Совет"},{"t":"Попробуй дыхание: вдох 4, задержка 7, выдох 8. Мне очень помогало, когда была сильная тревога.","e":"Даёт технику вместо признания.","g":"Рецепт"},{"t":"Мама не понимает, старшее поколение так воспитано. Не обижайся, она правда не со зла, она просто не знает.","e":"Оправдывает маму, просит «не обижаться».","g":"Защита обидчика"},{"t":"Ты рассказал маме, друзьям — и всё равно остался один с этим. Это очень одиноко.","e":"Фокус на изоляции как отдельном переживании поверх самих атак.","g":"Валидация","ok":1}]},{"s":"Женя шёпотом:\n«У дочки в классе все с айфонами. Попросила. Денег нет. Купила андроид. Она: \"Спасибо\", но я видела, как расстроилась. Чувствую, что я плохая мать, не могу дать то, что у всех есть».","o":[{"t":"«Чувствую себя плохой матерью» — это очень тяжело носить. Особенно когда делаешь всё что можешь.","e":"Признаёт тяжесть самого чувства вины.","g":"Валидация","ok":1},{"t":"Айфон не показатель любви, Жень. Ты дала что могла. Подрастёт, поймёт и будет благодарна.","e":"Отрицает вину вместо признания.","g":"Утешение"},{"t":"Оформи рассрочку или подожди скидок. Сейчас много вариантов, необязательно покупать новый.","e":"Решает проблему вместо поддержки.","g":"Совет"},{"t":"Не воспитывай потребителя, Жень. Пусть учится ценить что есть. Это даже полезно будет ей в жизни.","e":"Переворачивает ситуацию в воспитательную задачу.","g":"Морализация"}]},{"s":"Полина после защиты:\n«Получила \"отлично\". Все поздравляют, мама плачет. А я думаю: комиссия добрая попалась. Если бы строже, завалили бы. Даже порадоваться не могу. Что со мной не так?»","o":[{"t":"Ты получила \"отлично\"! Это объективная оценка! Хватит накручивать, порадуйся хоть раз в жизни!","e":"Требует радости, отрицает переживание.","g":"Бодрящее отрицание"},{"t":"Не мочь порадоваться своему успеху — это тяжело.","e":"Называет вторичную боль — невозможность почувствовать свой успех.","g":"Валидация","ok":1},{"t":"Это классический синдром самозванца, погугли. Когда понимаешь, что это паттерн, становится легче.","e":"Ставит ярлык вместо признания.","g":"Диагноз"},{"t":"Все так иногда чувствуют. Я тоже после экзаменов думала, что незаслуженно. Пройдёт, не переживай.","e":"Обесценивает через «все так», обещает пройдёт.","g":"Минимизация"}]},{"s":"Стас из Амстердама:\n«Тут я \"русский\". Дома: \"ты уже не наш, европейский\". Нигде не свой. На корпоративе не понимаю шутки. Маме звоню, она: \"а у нас снег\", и чувствую, что предал... Потому что вырос из того места, откуда уехал».","o":[{"t":"Там ты русский, тут ты европейский — и везде немного чужой. Это не ты не вписываешься. Это просто очень неудобное место, в котором ты сейчас находишься.","e":"Отражает раздвоенность без оценки, снимает личную вину.","g":"Валидация","ok":1},{"t":"Ты не предал, просто живёшь свою жизнь. Со временем найдёшь баланс, многие через это проходят.","e":"Отрицает чувство предательства, обещает баланс.","g":"Утешение"},{"t":"Нормально для экспатов. Первые пару лет все так. Потом найдёшь свою тусовку, и станет проще.","e":"Обесценивает через «все так», даёт прогноз.","g":"Минимизация"},{"t":"Чаще езди домой или найди русскоязычное сообщество в Амстердаме. Поможет почувствовать себя своим.","e":"Решает проблему вместо признания.","g":"Совет"}]},{"s":"Надя тихо:\n«Выкидыш. 8 недель. Мы ещё никому не говорили. И теперь горюю, а вокруг обычный день. Подруга: \"Ну 8 недель — это ещё не ребёнок\". Потом час в ванной плакала».","o":[{"t":"Подруга не хотела обидеть. Люди не знают, что сказать в такие моменты. Она не понимает, каково это.","e":"Оправдывает подругу, уводит от боли Нади.","g":"Защита обидчика"},{"t":"На раннем сроке такое бывает часто, организм не дал развиться. В следующий раз получится, не отчаивайся.","e":"Повторяет обесценивание в другой форме.","g":"Минимизация"},{"t":"Ты потеряла ребёнка. Не «8 недель», не «ещё рано». Ребёнка. Горевать — твоё право.","e":"Называет потерю прямо, защищает право на горе.","g":"Валидация","ok":1},{"t":"Мне жаль, Надь. Ты сильная, справишься. Может, стоит поговорить с психологом, который работает с потерей?","e":"Утешение + направление к специалисту вместо признания.","g":"Совет"}]},{"s":"Глеб, 19 лет:\n«Родители хотят, чтобы стал юристом, как отец. А я хочу развиваться в музыке. Записался на курсы продакшена. Мама узнала, уже два дня молчит. Отец: \"Делай что хочешь, но потом не жалуйся\". Как будто дали свободу и тут же наказали за неё».","o":[{"t":"Но подумай реально: музыка нестабильна. Может, совместить? Юридическое не помешает как запасной вариант.","e":"Встаёт на сторону родителей.","g":"Совет"},{"t":"Мама молчит, отец «разрешил», но с угрозой. «Делай что хочешь, но не жалуйся» — это не свобода, Глеб. Это наказание.","e":"Называет ловушку прямо. Переименовывает: не «разрешение», а ловушка.","g":"Валидация","ok":1},{"t":"Это их страх, не твоя проблема. Живи своей жизнью, привыкнут. Все родители сначала против.","e":"Обесценивает боль через «все так».","g":"Минимизация"},{"t":"Поддерживаю тебя, Глеб! Музыка это круто. Верь в себя, у тебя получится, я уверен, ты талантливый!","e":"Поддерживает решение, но не признаёт чувства.","g":"Поддержка действия"}]},{"s":"Оля, 31 год, Амстердам:\n«Папе поставили диагноз. Не смертельно, но серьёзно. Мама говорит \"не приезжай, всё нормально\" — но я слышу как она устала. Билеты стоят как моя зарплата за месяц. И виза — не факт что выпустят обратно. Сижу тут, работаю, плачу налоги, хожу на йогу. Просто хочу быть рядом. Не могу».","o":[{"t":"Ты не можешь бросить всё и уехать, это нерационально. Папе помогут врачи, маме — соседи.","e":"Аргументирует вместо признания.","g":"Логика"},{"t":"Надо копить на билеты, может попросить помощи у друзей. И с визой — юристы иногда помогают найти выход.","e":"Решает проблему вместо поддержки.","g":"Совет"},{"t":"Они же сами говорят что всё нормально. Доверяй им, они справятся.","e":"Принимает фасад за реальность.","g":"Минимизация"},{"t":"Мама говорит «не приезжай» — но ты слышишь другое. И не можешь ни поехать, ни перестать думать об этом.","e":"Называет противоречие, признаёт ловушку без выхода.","g":"Валидация","ok":1}]},{"s":"Дима, 38 лет:\n«Сын два года не звонит. Я виноват, знаю. Развод был тяжёлый, наговорил лишнего. Потом пытался мириться — не берёт трубку. Бывшая говорит что он сам так решил, не она. Может и правда. Смотрю на его фотографии, он уже другой. Я пропустил».","o":[{"t":"Не сдавайся, пиши письма, оставляй сообщения. Дети всегда в итоге возвращаются к родителям.","e":"Обещает то, что не может гарантировать.","g":"Ложное обещание"},{"t":"Ты сам признаёшь что виноват. Значит надо работать над собой, идти к психологу, меняться. Тогда сын увидит.","e":"Перескакивает к плану, игнорирует боль.","g":"Совет"},{"t":"Смотришь на фотографии — и он уже другой. Ты это пропустил, и знаешь это. Нести такое молча очень тяжело.","e":"Называет конкретную боль — необратимость.","g":"Валидация","ok":1},{"t":"Бывшая могла повлиять, дети в таком возрасте легко внушаемы. Не вини себя так сильно.","e":"Переводит стрелки, отрицает вину.","g":"Защита + минимизация"}]},{"s":"Оля листает инстаграм:\n«Подруга выложила фото с Бали: муж, ребёнок, океан. А я в съёмной однушке, после развода, с кредитом. Злость на неё.».","o":[{"t":"Я завистливая и мелочная. Она ничего мне не сделала. Надо удалить инстаграм и перестать сравнивать.","e":"Осуждает себя за чувство.","g":"Самобичевание"},{"t":"Мне плевать на её Бали. Каждый живёт как хочет. У меня свой путь, и мне за него не стыдно.","e":"Блокирует чувство бравадой.","g":"Отрицание"},{"t":"Хватит листать ленту, займусь своей жизнью. Злость — энергия, направлю её в дело, на что-то полезное.","e":"Переводит в задачу, не признаёт боль.","g":"Рефрейминг"},{"t":"Злость на неё — но дело не в ней. Просто её фото попало прямо в то, что сейчас болит.","e":"Снимает вину за злость, называет механизм.","g":"Самовалидация","ok":1}]},{"s":"Лиза:\n«Три часа слушала, как у Кати всё классно. А когда начала говорить про свои проблемы, она: \"ой, мне пора, созвонимся!\" И ушла».","o":[{"t":"Подожди — три часа ты слушала про неё, а когда твоя очередь — «ой, пора»? Серьёзно? И как ты себя после этого чувствовала?","e":"Повтор контраста с возмущением, потом — вопрос.","g":"Валидация","ok":1},{"t":"Может, ей правда надо было бежать. Не все замечают такие вещи. В следующий раз начни с себя первая.","e":"Оправдывает Катю, даёт совет.","g":"Защита + совет"},{"t":"Знакомо. У меня такая же подруга — только про себя. Перестала звонить — и стало легче, реально.","e":"Переключает на себя.","g":"Перетягивание"},{"t":"Может, Катя не тот человек для таких разговоров? Найди кого-то, кто умеет слушать, не все такие.","e":"Решает вместо признания.","g":"Совет"}]},{"s":"Филипп, тихо:\n«Странная штука — мне вроде нормально. Не болит ничего, не случилось ничего. Но я прихожу с работы и просто ложусь. Каждый день. Жена спрашивает \"что с тобой\" — а я не знаю, что ответить. Ничего вроде».","o":[{"t":"Слушай, может тебе просто отдохнуть нормально? Возьми отпуск, съезди куда-нибудь — вернёшься другим человеком.","e":"Предлагает решение, не признаёт состояние.","g":"Совет"},{"t":"Ничего не случилось — а сил нет. Иногда это даже труднее, чем когда есть причина.","e":"Легитимизирует состояние без видимого повода.","g":"Валидация","ok":1},{"t":"Фил, это звучит как депрессия. Сходи к врачу, серьёзно. Сейчас с этим нормально работают, таблетки, терапия.","e":"Ставит ярлык, отправляет к врачу.","g":"Диагноз"},{"t":"Может, работу пора менять? Каждый день одно и то же — понятно, что тошнит. Подумай, чего ты вообще хочешь от жизни.","e":"Интерпретирует причину, даёт совет.","g":"Совет"}]},{"s":"Ева ночью:\n«Тревога без причины. Ничего не случилось, а внутри сжимает. И бесит, что не могу объяснить. \"Из-за чего тревожишься?\" — \"Не знаю\". Звучит тупо».","o":[{"t":"Просто тревога, у всех бывает. Надо выдохнуть, чай, книжка, и пройдёт. Не накручивай себя.","e":"Обесценивает через «у всех», даёт рецепт.","g":"Минимизация"},{"t":"Наверное, из прошлого что-то. Надо к терапевту, разобраться в причинах, системно подойти к вопросу.","e":"Интерпретирует, отправляет к специалисту.","g":"Совет"},{"t":"Мне плохо, и не знаю почему. Не значит, что выдумываю. Тревога без причины — тоже тревога. Не обязана объяснять.","e":"Принимает тревогу без причины, снимает стыд.","g":"Самовалидация","ok":1},{"t":"Перестану думать. Чем больше думаю, тем хуже. Завтра новый день, пройдёт, всё всегда проходит.","e":"Блокирует чувство, обещает «пройдёт».","g":"Подавление"}]},{"s":"Илья:\n«Перевёл 200 тысяч мошенникам. Позвонили из \"банка\", запаниковал, перевёл. Когда понял, руки тряслись. Жене сказал, а она: \"Как ты мог повестись?! Ты что, совсем?\"»","o":[{"t":"Мошенники сейчас продвинутые, так давят, любой попадётся. Не вини себя, это не твоя вина, серьёзно.","e":"Отрицает вину полностью, минимизирует.","g":"Утешение"},{"t":"200 тысяч ушли — это само по себе кошмар. А дома вместо «я с тобой», «как ты мог?» Это второй удар, Илья. Тебя обманули — ты не дурак.","e":"Называет двойной удар. Не советует, просто видит.","g":"Валидация","ok":1},{"t":"Напиши заявление в полицию и в банк, срочно. Иногда деньги возвращают. Главное, действовать быстро.","e":"Перескакивает к действию.","g":"Совет"},{"t":"Ужасно, конечно. Но урок на будущее: никогда не переводи по телефону. Зато теперь точно будешь знать.","e":"Превращает боль в «урок».","g":"Морализация"}]},{"s":"Даня (10 лет) тихо, не смотрит в глаза:\n«Пап, я не хочу на футбол больше. Тренер кричит, ребята смеются, когда я мяч не ловлю. Я туда иду, и живот болит. Но ты же хотел, чтобы я играл...»","o":[{"t":"Дань, все через это проходят. В начале всем тяжело! Дай себе ещё месяц, втянешься и будет нравиться.","e":"Обесценивает через «все так», давит продолжать.","g":"Минимизация"},{"t":"Хорошо, не хочешь, не ходи. Займёмся чем-то другим. Плавание, карате, что захочешь, выбирай!","e":"Решает за ребёнка, не признаёт чувства.","g":"Быстрое решение"},{"t":"Я поговорю с тренером, чтобы не кричал. И с ребятами разберусь. Не переживай, всё будет нормально.","e":"Обещает починить, не слышит ребёнка.","g":"Ложное обещание"},{"t":"Слушай, живот перед тренировкой — это не про футбол. Это тело говорит, что тебе там тяжело. И что ты мне сказал, а не молчал — это важно, Дань.","e":"Связывает телесный симптом с чувством, хвалит за честность.","g":"Валидация","ok":1}]},{"s":"Света, 29 лет, внутренний монолог:\n«Получила оффер в Берлине. Хороший. Такого тут не будет. Но мама только что вышла на пенсию, подруга замуж выходит в июне, племянник растёт — я его почти не вижу уже сейчас. Если уеду — всё это будет в телефоне. Фотками. Голосовыми. А я хочу быть там живая. И в Берлине тоже хочу. Одновременно. Это же невозможно».","o":[{"t":"Света, такие офферы не ждут. Семья поймёт, будешь летать на праздники — сейчас это реально.","e":"Давит на решение, обещает «семья поймёт».","g":"Совет"},{"t":"Ну и оставайся тогда. Семья важнее карьеры, потом не пожалеешь.","e":"Выбирает сторону, не видит ловушку.","g":"Упрощение"},{"t":"Может, дело не в том, что не могу выбрать. А в том, что оба варианта чего-то стоят.","e":"Переформулирует «не могу» как «есть что терять».","g":"Самовалидация","ok":1},{"t":"Это твой шанс, Свет. Племянник вырастет, поймёт. Жизнь одна.","e":"Обесценивает привязанности ради карьеры.","g":"Давление"}]},{"s":"Рита, 31 год, подруге за кофе:\n«Он хороший. Правда. Заботливый, надёжный, не пьёт, не изменяет. Мама говорит \"золото, держись\". И я держусь. Но когда он входит в комнату — ничего не происходит. Три года уже. Думаю: может это я сломана. Может так и должно быть после трёх лет. Может я просто избалована романтикой из кино».","o":[{"t":"Мама говорит держись — и ты держишься. Только не понимаешь за что именно держишься.","e":"Называет механический характер «правильного» поведения.","g":"Валидация","ok":1},{"t":"Рит, страсть уходит у всех. Это нормально, главное уважение и доверие. Ты просто повзрослела.","e":"Обесценивает через «у всех так».","g":"Минимизация"},{"t":"Если ничего не чувствуешь три года — зачем мучить и себя и его? Надо честно поговорить.","e":"Давит на решение вместо признания.","g":"Совет"},{"t":"Может просто скука? Внеси что-то новое — путешествие, совместное хобби. Отношения надо поддерживать.","e":"Предлагает починку, не признаёт пустоту.","g":"Совет"}]},{"s":"Алина, подруге:\n«Я всегда первая. Пишу, спрашиваю как дела, приезжаю когда плохо. На прошлой неделе у меня был тяжёлый день — написала одной, второй. Обе прочитали. Одна ответила через сутки \"ой прости, закрутилась\". Вторая вообще не ответила».","o":[{"t":"Люди просто заняты, Алин. Не стоит обижаться — это не значит что им всё равно. Напомни о себе ещё раз.","e":"Оправдывает, просит «не обижаться».","g":"Минимизация"},{"t":"Ты поддерживаешь друзей, когда им плохо. А тебе даже не отвечают. Разница ощутимая.","e":"Называет дисбаланс коротко и точно.","g":"Валидация","ok":1},{"t":"Значит это не твои люди. Окружение надо чистить — кто не отвечает, тот не друг.","e":"Выносит вердикт вместо признания боли.","g":"Приговор"},{"t":"Может, ты слишком много даёшь? Люди привыкают. Попробуй меньше делать — посмотришь кто останется.","e":"Обвиняет Алину в чрезмерной заботе.","g":"Совет"}]}]},{"id":"find_invalid","tt":"Найди инвалидацию","ds":"Найди обесценивающий ответ","sm":"i","ins":["Прочитай ситуацию","Найди один обесценивающий среди валидирующих","Остальные три — настоящая валидация"],"dt":[{"s":"Марина шёпотом: «Лучшую подругу повысили. Я улыбалась, поздравляла. Дома рыдала. Не потому что не рада. А потому что завидно. И тошно от себя — какой я после этого человек».","o":[{"t":"«Зависть — это сигнал. Значит, тебе тоже хочется роста. Используй это как мотивацию.»","e":"Рефрейминг. Не признаёт чувство, а сразу переводит его в задачу.","inv":1},{"t":"«Радоваться и завидовать одновременно — не делает тебя плохой. Это делает тебя живым человеком.»","e":"Называет оба чувства без осуждения."},{"t":"«Тошно от себя за зависть — это отдельная тяжесть. Стыдиться чувства поверх самого чувства.»","e":"Признаёт стыд как отдельный слой."},{"t":"«Улыбалась, поздравляла — и дома рыдала. Это очень одиноко — носить такое внутри.»","e":"Называет одиночество."}]},{"s":"Саша после ссоры: «Опять сорвался из-за ерунды. Жена просто спросила про ужин, а я начал орать. Какой же мудак. Она не заслуживает такого».","o":[{"t":"«Сорвался — и мне хреново от этого. Значит, мне не всё равно.»","e":"Признаёт что хреново — и связывает это с тем что не всё равно."},{"t":"«\"Она не заслуживает\" — это говорит что мне важно как с ней. Это не мудак. Это человек который дорожит.»","e":"Переосмысляет «не заслуживает» как заботу."},{"t":"«Я не мудак — я устал и не справился. Разные вещи.»","e":"Разделяет поступок и личность."},{"t":"«Надо научиться контролировать эмоции. Запишусь к психологу, начну медитировать.»","e":"План действий. Пропускает контакт с чувством, сразу переключается на исправление.","inv":1}]},{"s":"Полина после защиты: «Получила \"отлично\". Все поздравляют, мама плачет. А я думаю: комиссия добрая попалась. Если бы строже — завалили бы. Даже порадоваться не могу. Что со мной не так?»","o":[{"t":"«Не мочь порадоваться своему успеху — это тяжело само по себе.»","e":"Называет вторичную боль — невозможность почувствовать успех."},{"t":"«Со временем это пройдёт. Когда защитишь следующую работу — будет легче присваивать результат.»","e":"Непрошеный оптимизм с переносом в будущее. Обесценивает текущую боль.","inv":1},{"t":"«\"Что со мной не так\" — но с тобой всё так. Просто очень давно не разрешала себе быть достаточной.»","e":"Отвечает на вопрос мягко и без диагноза."},{"t":"«Все поздравляют, а внутри пусто. Это отдельная боль — когда праздник есть, а войти в него не получается.»","e":"Называет разрыв между внешним праздником и внутренней пустотой."}]},{"s":"Стас из Амстердама: «Тут я \"русский\". Дома: \"ты уже не наш, европейский\". Нигде не свой. На корпоративе не понимаю шутки. Маме звоню, она: \"а у нас снег\" — и чувствую что предал. Кого, не знаю. Наверное всех».","o":[{"t":"«\"Предал всех\" — это очень тяжело носить. Особенно когда даже не можешь сказать кого именно.»","e":"Признаёт чувство вины и его размытость как отдельную тяжесть."},{"t":"«Маме звонишь — и вместо близости ещё дальше. Это особенно больно когда именно от неё ждёшь тепла.»","e":"Называет конкретный момент боли."},{"t":"«Это нормально для экспатов. Первые пару лет все так. Потом найдёшь свою тусовку и станет проще.»","e":"Обесценивает через «у всех бывает». «Найдёшь тусовку» — непрошеный оптимизм.","inv":1},{"t":"«Там русский, тут европейский — и везде немного чужой. Это не ты не вписываешься. Это просто очень неудобное место.»","e":"Признаёт раздвоенность, снимает личную вину."}]},{"s":"Ева ночью: «Тревога без причины. Ничего не случилось, а внутри сжимает. И бесит что не могу объяснить. \"Из-за чего тревожишься?\" — \"Не знаю\". Звучит тупо».","o":[{"t":"«Тревога без причины — тоже тревога. Не обязана объяснять.»","e":"Убирает требование объяснить — тревога без причины тоже настоящая."},{"t":"«Наверное, из прошлого что-то. Надо разобраться в причинах — может к терапевту.»","e":"Сразу поиск причины и направление к терапевту. Ева не просила помочь разобраться.","inv":1},{"t":"«Бесит что не могу объяснить — это отдельное. Злость на себя за то что непонятно.»","e":"Называет второй слой — злость на себя за непонимание."},{"t":"«Мне плохо — и не знаю почему. Не значит что выдумываю.»","e":"Признаёт состояние без оправданий."}]},{"s":"Артём: «Сократили. Восемь лет в компании. Письмо пришло в девять утра, доступ отключили, пока я его читал. В HR сказали: ничего личного, оптимизация. У меня там кружка осталась в офисе. И кроссовки под столом. В пятницу поехал забирать, дошёл до машины с этой коробкой и разревелся на парковке. Первый раз лет за пятнадцать».","o":[{"t":"«Восемь лет, а попрощались автоматическим письмом. Меня бы это добило.»","e":"Признаёт несоразмерность, говорит от себя."},{"t":"«Ничего личного, ага. Это для них не личное. А там твоя кружка и восемь лет.»","e":"Подхватывает его же детали, встаёт на его сторону."},{"t":"«Да всё к лучшему! Отдохнёшь, а с твоим опытом ещё и получше найдёшь.»","e":"Перепрыгивает потерю и сразу назначает ей счастливый финал.","inv":1},{"t":"«Ты же не только работу потерял. Там люди были, привычки, вся жизнь по будням.»","e":"Замечает, что потеря не одна."}]},{"s":"Юля: «Дочке четыре месяца. Я её люблю, правда. Но муж уходит в восемь, приходит в семь, подруги как вымерли. В четверг курьер сказал \"хорошего дня\", и меня накрыло так, что я минут десять стояла в подъезде с пакетом и не могла зайти домой. Из-за «хорошего дня», представляешь».","o":[{"t":"«Наслаждайся! Они так быстро растут, потом будешь скучать по этому времени.»","e":"Вместо ответа на одиночество требует радоваться. После такого жаловаться ещё стыднее.","inv":1},{"t":"«Целый день с ребёнком и без единого взрослого рядом. Конечно тебя от курьера накрыло.»","e":"Связывает слёзы с реальной причиной, без паники и оценок."},{"t":"«Десять минут в подъезде из-за «хорошего дня». Это сколько же ты сидишь без нормального разговора.»","e":"Видит за мелочью масштаб дефицита."},{"t":"«А подруги-то куда делись, когда ты тут одна с четырёхмесячной. Обидно же.»","e":"Замечает потерю круга как отдельную вещь."}]},{"s":"Кира: «Три месяца встречались. Я с его друзьями на дачу ездила, отпуск обсуждали. Неделю назад он просто перестал отвечать. Не заблокировал, сообщения читает. Я в среду до трёх ночи перечитывала переписку, искала, где накосячила».","o":[{"t":"«Читает и молчит. По-моему это жёстче, чем блок: надежда каждый раз обновляется.»","e":"Признаёт мучительность именно этой формы исчезновения."},{"t":"«Скажи спасибо, что слился сейчас, а не через два года. Он тебя недостоин, выдыхай и вперёд.»","e":"Отменяет право горевать: было же «к счастью».","inv":1},{"t":"«Ты до трёх ночи ищешь свой косяк, потому что он ничего не объяснил. Голове нужен виноватый, и обычно она находит тебя.»","e":"Показывает, откуда берётся самообвинение."},{"t":"«Три месяца были настоящие. Дача, планы. Нормально по этому скучать и злиться на него, можно всё сразу.»","e":"Разрешает противоречивые чувства, не выбирая за неё."}]},{"s":"Инна: «У меня аутоиммунное. По анализам всё серьёзно, по мне не скажешь. Внутри как грипп, который четвёртый год не проходит. На той неделе коллега выдала: \"мне бы твои болячки, ты вон румяная какая\". Я улыбнулась и пошла работать. А вечером дома наорала на дочь из-за невымытой чашки».","o":[{"t":"«Болеть так, что приходится ещё и доказывать, что болеешь. Это же двойная работа.»","e":"Называет вторую нагрузку, которую даёт невидимость."},{"t":"«Румяная. А внутри четвёртый год грипп. И никто не видит, вот в чём засада.»","e":"Проговаривает разрыв её же словами."},{"t":"«Ну ты правда хорошо выглядишь! И вообще, люди вон с онкологией живут, у тебя ещё терпимо.»","e":"Та же «румяная», только вежливее. Плюс сравнение, после которого жаловаться неловко.","inv":1},{"t":"«И ведь каждому новому человеку объясняй заново. Я бы от одних объяснений устала.»","e":"Замечает усталость от доказательств, присоединяется."}]},{"s":"Вера: «Мы с Наташей дружили с института, двадцать лет. Не ссорились. Просто она стала отвечать через день, потом через неделю, а на моё \"с днём рождения\" в марте — тишина. У меня половина жизни с ней связана, а спросить \"что случилось\" уже как-то глупо».","o":[{"t":"«Двадцать лет, и закончилось без единого события. Даже непонятно, с какого дня это считать.»","e":"Признаёт, что горевать без точки труднее."},{"t":"«Половина жизни. Это потеря, самая настоящая, хоть никто не умер и не ссорился.»","e":"Даёт горю статус, которого ему не хватает."},{"t":"«И спросить не у кого, вот что паршиво. Все вопросы остались тебе.»","e":"Называет одиночество и безответность."},{"t":"«Люди перерастают друг друга, это нормально. Отпусти её с благодарностью за хорошие годы.»","e":"Красивые слова, которыми закрывают тему. «Отпусти» — команда, а не сочувствие.","inv":1}]}]},{"id":"vs_indulgence","tt":"Валидация или потакание","ds":"Отличи валидацию от потакания","sm":"c","ins":["Прочитай ситуацию","Выбери валидацию — не потакание","Потакание поддерживает действие, не чувство"],"dt":[{"s":"Игорь: «Провалил презентацию. Голос дрожал, забыл половину. Все видели. Коллега написал \"бывает\" — хочу ответить ему что-нибудь такое чтобы он заткнулся».","o":[{"t":"Провалиться когда все смотрят — отдельная боль. Не просто ошибка.","e":"Признаёт боль публичного провала. Не трогает действие.","ok":1},{"t":"Напиши, нечего было лезть с утешениями.","e":"Поддерживает действие."},{"t":"Правильно, пусть знает что не надо лезть.","e":"Поддерживает злость и действие."}]},{"s":"Света: «Мама третий год болеет. Я всё бросила, переехала. Сегодня она сказала что я недостаточно забочусь. Хочу уехать и не отвечать на звонки неделю».","o":[{"t":"Уезжай, ты имеешь право на передышку.","e":"Поддерживает уход как решение, не признаёт боль."},{"t":"Три года отдавать всё — и услышать что мало. Это очень больно.","e":"Признаёт несправедливость и боль. Не трогает действие.","ok":1},{"t":"Правильно, пусть побудет одна — поймёт.","e":"Поддерживает действие и добавляет мотив мести."}]},{"s":"Ника: «Подруга потеряла работу — все вокруг носятся с ней. А я полгода в депрессии и никто не спрашивает. Хочу написать общим друзьям что мне тоже плохо».","o":[{"t":"Пиши, имеешь полное право — ты тоже заслуживаешь внимания.","e":"Поддерживает действие и усиливает."},{"t":"Напиши, люди просто не замечают — надо говорить.","e":"Поддерживает действие с обоснованием."},{"t":"Полгода плохо — и при этом быть невидимой. Это обидно.","e":"Признаёт боль невидимости. Не трогает действие.","ok":1}]},{"s":"Андрей: «Бывшая выложила фото с новым — путешествие, смеётся. Мы расстались полгода назад. Хочу поставить лайк — пусть видит что мне не всё равно».","o":[{"t":"Видеть её счастливой когда самому больно — это тяжело.","e":"Признаёт боль. Не трогает действие.","ok":1},{"t":"Ставь, пусть знает что ты следишь и помнишь.","e":"Поддерживает действие и добавляет скрытый мотив."},{"t":"Лайкни, что такого — просто лайк.","e":"Поддерживает действие, минимизируя его."}]},{"s":"Марина: «Все идут ко мне с проблемами. Подруга снова звонит в слезах — час разговора. Хочу не брать трубку и вообще отключить телефон на неделю».","o":[{"t":"Правильно, пусть поищет кого-то другого.","e":"Поддерживает отстранение."},{"t":"Не бери, ты не обязана всегда быть доступной.","e":"Поддерживает действие через права."},{"t":"Всегда быть той на кого можно опереться — это изматывает.","e":"Признаёт усталость от роли. Не трогает действие.","ok":1}]},{"s":"Павел: «После сокращения бывший шеф выложил в линкедин пост про \"оптимизацию с заботой о людях\". Двести лайков. Мне хочется написать под этим постом, как эта забота выглядела изнутри. Прямо руки чешутся».","o":[{"t":"Тебя сократили письмом, а он собирает лайки за заботу. Меня бы тоже трясло.","e":"Разделяет злость. В пост не лезет.","ok":1},{"t":"Напиши. Пусть люди знают, как оно было на самом деле.","e":"Подталкивает к действию под флагом правды."},{"t":"Давно пора таких выводить на чистую воду. Публично — самое то.","e":"Одобряет и действие, и месть."}]},{"s":"Оксана: «Первый муж изменял два года, и я реально ничего не видела. Сейчас всё хорошо, человек надёжный. Но в субботу он ушёл в душ, телефон остался на кухне, и я просидела рядом с ним, пока вода не выключилась. Один раз посмотрю и успокоюсь, я же себя знаю».","o":[{"t":"Посмотри один раз и закрой тему. Хуже всего месяцами себя накручивать.","e":"Обещает покой через проверку."},{"t":"Два года тебя обманывали у тебя под носом. Понятно, почему теперь любой телефон на кухне гудит как сирена.","e":"Объясняет страх историей. Телефон не трогает.","ok":1},{"t":"После такого ты имеешь право проверять. Кому не нравится, пусть докажет, что чист.","e":"Оформляет проверку как право и выставляет счёт новому партнёру."}]},{"s":"Лариса: «Свекровь опять в семейном чате: \"ребёнок худенький, ну а что вы хотите, мама у нас готовить не любит\". Со смайликом. Третий раз за месяц. Муж молчит, его сестра ставит хаха. Я уже набрала ответ, палец над кнопкой».","o":[{"t":"Ответь там же, при всех. Она публично, и ты публично, всё честно.","e":"Разрешает ответить тем же, раз она первая начала."},{"t":"Пора её осадить раз и навсегда. Иначе так и будет ездить.","e":"Подталкивает и добавляет срочности: иначе будет хуже."},{"t":"Третий раз при всей семье. Муж молчит, золовка хахакает. Тут дело уже не в свекрови даже: тебя никто не прикрыл.","e":"Замечает главную рану, бездействие своих. Кнопку не трогает.","ok":1}]},{"s":"Кирилл: «Шеф на планёрке двадцать минут разбирал мой проект. \"Детский сад\", \"стыдно показывать клиенту\". При всех. Я сидел и кивал. Сейчас открыл ворд с заявлением. Плевать, что ипотека, я туда завтра не пойду».","o":[{"t":"Двадцать минут при всех, а ты сидел и кивал. Я бы после такого тоже открыл ворд.","e":"Признаёт унижение и желание. Заявление не благословляет.","ok":1},{"t":"Подавай. Здоровье и самоуважение дороже ипотеки.","e":"Благословляет действие ценностью, ипотеку отодвигает."},{"t":"И правильно, хлопни дверью погромче. Такие только так и учатся.","e":"Соглашается с уходом и добавляет мотив проучить."}]},{"s":"Майя: «Третий год ЭКО, вторая неудачная попытка была в мае. В воскресенье Ленка прислала фото УЗИ: \"скоро нас будет трое!!!\" Я написала \"ура, поздравляю\" и выключила телефон до утра. Хочу скрыть её сториз и месяц-два не общаться. Со всеми беременными так делаю, уже целый список».","o":[{"t":"Скрой и не общайся. Ты никому не обязана смотреть на чужие животы.","e":"Поддерживает избегание, назвав его заботой о себе."},{"t":"Написала «ура» и выключила телефон до утра. Три года попыток, конечно чужое УЗИ бьёт наотмашь. И за Ленку ты правда рада, это тоже слышно.","e":"Признаёт обе стороны и цену за ними. Список не комментирует.","ok":1},{"t":"Вообще-то подруга могла бы подумать, прежде чем кидать тебе УЗИ. Так что всё справедливо.","e":"Одобряет и назначает виноватую."}]}],"cn":"Потакание — это когда мы поддерживаем действие или решение, вместо того чтобы признать чувство. Валидация говорит «тебе больно» — потакание говорит «ты прав, делай так». Разница огромна: валидация помогает опереться на себя, а потакание усиливает импульс и мешает человеку самому разобраться."},{"id":"layers","tt":"Разные слои","ds":"Отметь все валидирующие","sm":"m","ins":["Прочитай ситуацию","Отметь все слои, которые точно валидируют","Два из пяти — мимо, три — точные"],"dt":[{"s":"Руслан: «Повысили. Все поздравляют. Жду когда скажут что ошибка. Макс работает лучше, Лена умнее. Мне просто повезло».","o":[{"t":"Мучительное ожидание разоблачения","e":"«Жду когда скажут что ошибка» — центральное переживание. Названо прямо.","v":1},{"t":"Усталость от внутреннего голоса — он звучит давно","e":"«Макс лучше, Лена умнее» — не свежая мысль. Голос работает давно.","v":1},{"t":"Страх не оправдать доверие тех кто повысил","e":"Вектор другой. Руслан не боится подвести начальство — он боится что его раскроют."},{"t":"Одиночество в тревоге пока все празднуют","e":"Контраст между праздником снаружи и страхом внутри. Он один в этом.","v":1},{"t":"Обида что достижение не приносит радости","e":"Руслан не говорит про отсутствие радости. Он говорит про страх. Приписывает переживание, которого нет."}]},{"s":"Тимофей: «Макс выложил про миллион. Я знаю что это враньё — долги, жена ушла. Но все лайкают. И я завидую. Хотя знаю правду».","o":[{"t":"Противоречие между знанием и чувством","e":"«Знаю что враньё... и завидую» — голова знает одно, чувство делает другое.","v":1},{"t":"Стыд что завидуешь тому что сам считаешь фальшивым","e":"Тимофей не стыдится. Он говорит «я завидую» прямо, без смущения. Приписывает стыд."},{"t":"Бессилие — видишь правду и ничего не докажешь","e":"«Все лайкают» — он знает правду, но она никому не нужна. Бессилие перед картинкой.","v":1},{"t":"Одиночество — знаешь то чего не знают другие и молчишь","e":"Он один с этим знанием. Все лайкают, никто не видит того что видит он.","v":1},{"t":"Злость на людей которые ведутся на картинку","e":"Тимофей не злится на тех кто лайкает. Он говорит про себя, про свою зависть."}]},{"s":"Глеб: «Хочу музыку. Отец: \"делай что хочешь, но потом не жалуйся\". Мама молчит. Я не знаю — это поддержка или угроза».","o":[{"t":"Ловушка в разрешении","e":"«Делай что хочешь, но не жалуйся» — формально разрешение, по сути угроза.","v":1},{"t":"Мамино молчание как отдельный удар","e":"Мама молчит — и это не нейтральность. Глеб выделяет это отдельно — значит болит отдельно.","v":1},{"t":"Страх что если не получится — помощи не будет","e":"Глеб не про будущий провал. Он про сейчас: не может расшифровать послание."},{"t":"Растерянность — не знает радоваться или бояться","e":"«Не знаю — это поддержка или угроза» — буквально его слова.","v":1},{"t":"Чувство что его мечту не воспринимают всерьёз","e":"Глеб пришёл с растерянностью от двойного послания, а не с обидой что мечту не ценят."}]},{"s":"Лиза: «Три часа слушала Катю про её проблемы. Потом моя очередь — \"ой пора, созвонимся\". Больше не позвонила. Злюсь — но она не виновата, просто такой человек».","o":[{"t":"Дисбаланс","e":"Три часа слушала — её не выслушали. Неравное распределение внимания — факт, который болит.","v":1},{"t":"Разочарование в близости которая оказалась односторонней","e":"Лиза не обобщает до уровня отношений. Она злится на конкретный эпизод. Додумывание."},{"t":"Запрет на злость","e":"«Злюсь — но она не виновата» — классический самозапрет. Лиза злится и тут же отменяет себе право.","v":1},{"t":"Усталость от повторения","e":"«Больше не позвонила» — это не первый раз, это паттерн. Усталость от того что повторяется.","v":1},{"t":"Грусть что приходится выбирать между дружбой и своими границами","e":"Лиза не стоит перед выбором и не думает про границы. Приписывает рефлексию, которой пока нет."}]},{"s":"Филипп: «Ничего не случилось. Просто каждый день думаю — что-то не так. Жене не говорю. Она скажет \"ты устал, отдохни\"».","o":[{"t":"Нет причины — и от этого ещё труднее","e":"Отсутствие причины не облегчает, а усиливает. Нечем объяснить себе своё состояние.","v":1},{"t":"Страх что это начало чего-то серьёзного","e":"Филипп не говорит что боится диагноза. Он говорит что несёт это один. Додумывание."},{"t":"Одиночество — молчит потому что знает что не поймут","e":"«Жене не говорю» — заранее знает что не поймут. Вынужденное одиночество.","v":1},{"t":"Тихая боль каждый день — не острая, но не легче","e":"«Каждый день» — хроническая, фоновая боль. Точное название характера состояния.","v":1},{"t":"Раздражение что близкие сведут всё к усталости","e":"Филипп не раздражён. Он заранее знает реакцию и поэтому молчит. Это не злость, это усталое принятие."}]},{"s":"Тамара: «Приехала к маме, она посмотрела и спрашивает: \"Вы из соцзащиты?\" Потом узнала, засмеялась: \"Совсем я, старая, того\". Я досидела, чай попили, дома всем сказала, что нормально съездила. А в машине у подъезда просидела минут сорок, не могла ключ повернуть».","o":[{"t":"Терять маму, пока она жива","e":"Мама рядом, но узнавание уходит по кусочку. Это горе началось задолго до всяких похорон.","v":1},{"t":"Держать лицо до самой машины","e":"Чай, «нормально съездила», сорок минут в заглушенной машине. Столько стоит это «нормально».","v":1},{"t":"Злость на маму","e":"В рассказе злости нет. Есть чай, «нормально» и сорок минут в машине. Приписано."},{"t":"Одна с этим","e":"Домашним досталось «нормально съездила». Значит, разваливаться можно только в машине, и никто не знает, как ей на самом деле.","v":1},{"t":"Вина, что мало занимается мамой","e":"Про «мало» и «надо больше» ни слова. Додумано."}]},{"s":"Денис: «Сыну пятнадцать. Спрашиваю, как в школе — \"норм\". Как дела — \"норм\". И дверь закрывается. А года три назад мы с ним месяц собирали лего-звездолёт, он мне про каждую деталь рассказывал. Он вроде дома. А я по нему скучаю, как будто он уехал».","o":[{"t":"Скучать по тому, кто дома","e":"«Скучаю, как будто уехал» — его собственные слова. Сын за стенкой, и достучаться некуда.","v":1},{"t":"Горе по тем отношениям","e":"Звездолёт и рассказы про каждую деталь. Вот по чему тоска: того формата больше нет.","v":1},{"t":"Обида на неблагодарность","e":"Никакого «я ему всё, а он мне» тут нет. Есть тоска, счёта нет. Приписано."},{"t":"Бессилие","e":"Дверь закрывается, и снаружи её не откроешь. Разговаривать не заставишь, остаётся ждать.","v":1},{"t":"Страх плохой компании","e":"Ни про компанию, ни про тревогу за него ни слова. Додумано."}]},{"s":"Виктор: «Долг по двум кредиткам, восьмой месяц перекидываю с одной на другую. На работе анекдоты травлю, дома \"порядок, не переживай\". В воскресенье жена показывала отели на майские, я говорил \"ага, красиво\" и считал в голове минималку по платежу».","o":[{"t":"Страх, который всегда фоном","e":"Минималка считается даже во время разговора про отпуск. Тревога не выключается.","v":1},{"t":"Жизнь на два фронта","e":"Анекдоты на работе, «порядок» дома, а настоящее только у него в голове. Это выматывает само по себе.","v":1},{"t":"Одиночество рядом с женой","e":"Она выбирает отель, он рядом считает платёж. Ближе некуда, и сказать нельзя.","v":1},{"t":"Злость на банки","e":"Банков в его рассказе нет. Есть страх и молчание. Приписано."},{"t":"Сожаление о покупках","e":"Откуда долг, он не говорит, и за прошлое себя не казнит. Додумано."}]},{"s":"Людмила: «Дочка поступила в другой город, я сама её уговаривала ехать. Проводили в августе. Теперь захожу зачем-то в её комнату, посуды мою на треть меньше, и в квартире тихо так, что слышно холодильник. Ей там классно, звонит довольная. А я ей не говорю, что сижу иногда на её кровати просто так. Неловко: у неё же всё отлично».","o":[{"t":"Гордость и пустота одновременно","e":"Сама уговаривала ехать, дочь довольна. И посуды на треть меньше. Оба факта настоящие, друг друга не отменяют.","v":1},{"t":"Запрет себе на грусть","e":"«Не говорю, неловко». Грусть под замком, потому что у дочки-то всё хорошо.","v":1},{"t":"Обида на дочь","e":"Она сама её уговаривала ехать. Обиды в рассказе нет. Приписано."},{"t":"Тишина, которую слышно","e":"Холодильник стал слышен. Пустота в доме теперь буквально звучит.","v":1},{"t":"Страх остаться ненужной","e":"Про «я больше не нужна» она не говорит. Говорит про тишину и неловкость за собственную грусть. Додумано."}]}],"cn":"В одной ситуации человек может чувствовать сразу несколько вещей: обиду, стыд, одиночество, страх. Каждое из этих чувств — отдельный слой. Хорошая валидация видит не одно чувство, а несколько. Здесь нужно отметить те слои, которые точно описывают переживание — и отсечь те, что приписывают лишнее."},{"id":"meta","tt":"Метауровень","ds":"Какой метод здесь работает","sm":"c","ins":["Прочитай ситуацию","Выбери метод, который здесь сработает","Думай не «что сказать», а «как подойти»"],"dt":[{"s":"Карина тихо: «Мурка умерла вчера. 14 лет вместе. На работе все: \"Это же кошка, заведи другую\". Как будто она вещь».","o":[{"t":"Назови необратимость","e":"14 лет — не «просто кошка». Признать масштаб потери без попытки починить.","g":"Работает","ok":1},{"t":"Сними стыд за чувство","e":"Стыда здесь нет — Карина не стесняется боли. Проблема в обесценивании.","g":"Близко"},{"t":"Назови чувство","e":"Первый шаг. Но здесь важнее признать что именно потеряно.","g":"Поверхностно"},{"t":"Предложи контакт","e":"Контакт важен, но сначала признать масштаб потери.","g":"Не подходит"}],"m":"В теории горевания (Worden) первая задача — признать реальность потери. Когда окружающие обесценивают утрату («заведи другую»), горевание блокируется — человек теряет право на свою боль. «Назови необратимость» возвращает потере её вес и открывает возможность горевать.","ex":"«14 лет — это огромная часть жизни. Конечно, боль от этой потери очень глубокая.»"},{"s":"Гриша: «Панические атаки. Сердце колотится, руки трясутся, кажется умираю. Маме сказал — она: \"Это от телефона, погуляй\". Друзья: \"Ты много думаешь\". Как будто выдумываю».","o":[{"t":"Убери требование объяснить","e":"Гриша не жалуется что должен объяснять — он жалуется что не верят.","g":"Не тот контекст"},{"t":"Назови изоляцию как отдельный слой","e":"Изоляция есть, но сначала важнее признать само переживание.","g":"Второй слой"},{"t":"Признай телесный сигнал","e":"Сердце, руки, ощущение что умираешь — тело не врёт. Признать физическое переживание как реальное.","g":"Работает","ok":1},{"t":"Назови двойной удар","e":"Двойной удар есть: паника + «ты выдумываешь». Но сначала признать телесное переживание.","g":"Близко"}],"m":"При панических атаках тело генерирует сигнал смертельной угрозы — активация симпатической нервной системы, выброс адреналина. Когда окружающие говорят «ты выдумываешь», возникает газлайтинг телесного опыта. В somatic experiencing (Levine) признание телесных ощущений (tracking) — первый шаг к регуляции.","ex":"«То что ты описываешь — сердце, руки, ощущение что умираешь — это очень страшно переживать.»"},{"s":"Надя тихо: «Выкидыш. 8 недель. Мы ещё никому не говорили. И теперь горюю, а вокруг обычный день. Подруга: \"Ну 8 недель — это ещё не ребёнок\". Потом час в ванной плакала».","o":[{"t":"Сними стыд за чувство","e":"Стыд может быть, но центральная рана другая: право на потерю отрицается.","g":"Не центральное"},{"t":"Назови потерю прямо","e":"Без цифр, без условий. Назвать потерю — значит вернуть право на горе.","g":"Работает","ok":1},{"t":"Признай изоляцию как отдельный слой","e":"Изоляция есть, но без признания потери название изоляции не имеет опоры.","g":"Второй слой"},{"t":"Назови необратимость","e":"Необратимость — про масштаб. Здесь глубже: само право на потерю отрицается.","g":"Близко"}],"m":"Это «бесправное горе» (disenfranchised grief, Doka) — потеря, на которую общество не даёт права горевать. «8 недель — это ещё не ребёнок» — отрицание легитимности утраты. Человек теряет не только то что потерял, но и возможность об этом горевать. Назвать потерю прямо — дать горю право на существование.","ex":"«Ты потеряла ребёнка. Не \"8 недель\". Ребёнка. Горевать — твоё право.»"},{"s":"Арина: «Сказала Саше что обидно — не позвонил когда болела. А он: \"Ты опять драматизируешь, я был занят, хватит сцены устраивать\"».","o":[{"t":"Назови чувство","e":"«Тебе обидно» — правда, но не отражает что произошло два удара подряд.","g":"Поверхностно"},{"t":"Переименуй ловушку","e":"Арина не застряла в чужом слове — она возмущена им.","g":"Не тот контекст"},{"t":"Назови двойной удар","e":"Не позвонил — первый удар. Назвал боль «сценой» — второй. Назвать оба слоя.","g":"Работает","ok":1},{"t":"Признай вину не опровергая","e":"Арина не чувствует себя виноватой. Она обижена и обесценена.","g":"Нет вины"}],"m":"Двойной удар — когда реакция на боль причиняет вторую боль. В EFT (Sue Johnson) это «протестное поведение привязанности»: Арина сигнализирует что ей нужна связь, а в ответ получает обесценивание. Второй удар опаснее первого: он учит что говорить о боли небезопасно.","ex":"«Подожди — ты пришла сказать что обидно, а он это назвал \"сценой\"? Это двойной удар — сначала не позвонил, потом ещё и обесценил.»"},{"s":"Таня: «Бабушка в больнице. Мама ездит каждый день, а я не могу. Работа, дети, нет сил. Бабушка: \"Всё хорошо, не приезжай\". Но я знаю, ей плохо. И знаю, что потом буду жалеть».","o":[{"t":"Признай оба притяжения","e":"«Оба притяжения» — когда два желания тянут. У Тани не два равных желания, а невозможность выбора без потери.","g":"Близко"},{"t":"Назови ловушку","e":"Приехать — нет сил. Не приехать — сожрёт вина. Назвать саму ловушку честнее чем искать выход.","g":"Работает","ok":1},{"t":"Признай вину не опровергая","e":"Признать вину важно, но без названия ловушки признание вины звучит как согласие с ней.","g":"Преждевременно"},{"t":"Убери требование объяснить","e":"Таня не жалуется что должна объяснять. Она жалуется что нет хорошего выхода.","g":"Не тот контекст"}],"m":"Это «двойной зажим» (double bind, Bateson) — ситуация где любой выбор приводит к потере. Отличие от дилеммы: в дилемме есть лучший вариант, в двойном зажиме — нет. Попытка найти «правильное решение» усиливает страдание. Назвать ловушку — снять требование решить нерешаемое.","ex":"«Приехать — нет сил. Не приехать — сожрёт вина. И оба варианта не очень.»"},{"s":"Женя шёпотом: «У дочки в классе все с айфонами. Попросила. Денег нет. Купила андроид. Она: \"Спасибо\", но я видела как расстроилась. Чувствую что я плохая мать».","o":[{"t":"Назови чувство","e":"Женя уже сама назвала что чувствует. Повторить — не добавить ничего.","g":"Поверхностно"},{"t":"Сними стыд за чувство","e":"У Жени не стыд за чувство, а вина за ситуацию. Стыд и вина — разные эмоции.","g":"Не тот механизм"},{"t":"Переадресуй на настоящую рану","e":"Переадресовать точно, но преждевременно. Сначала признать само чувство вины.","g":"Второй шаг"},{"t":"Признай вину не опровергая","e":"«Ты не плохая мать» слишком рано — инвалидация. Сначала признать что чувство вины есть и что оно тяжело.","g":"Работает","ok":1}],"m":"В DBT (Linehan) это уровень 3 валидации — признание невысказанного. Женя говорит «плохая мать» — за этим вина. Рефлекс окружающих — опровергнуть: «нет, ты хорошая!» Но опровержение до признания = инвалидация. Человек слышит: «твоё чувство неправильное».","ex":"«\"Чувствую себя плохой матерью\" — это очень тяжело носить. Особенно когда делаешь всё что можешь.»"},{"s":"Алина подруге: «Я всегда первая. Пишу, спрашиваю как дела, приезжаю когда плохо. На прошлой неделе тяжёлый день — написала. Обе прочитали. Одна ответила через сутки. Вторая вообще не ответила».","o":[{"t":"Назови изоляцию как отдельный слой","e":"Изоляция есть. Но сначала важнее отразить дисбаланс.","g":"Второй слой"},{"t":"Эхо с удивлением","e":"Эхо реагирует на факт. Контраст точнее: показывает структуру дисбаланса.","g":"Близко"},{"t":"Назови контраст без вывода","e":"Отразить дисбаланс — не делать вывод за человека. Контраст сам говорит всё.","g":"Работает","ok":1},{"t":"Назови двойной удар","e":"Двойной удар — когда реакция на боль причиняет вторую боль. Здесь хронический дисбаланс.","g":"Не та структура"}],"m":"В мотивационном интервьюировании (Miller & Rollnick) есть принцип: не давать вывод, а создать условия чтобы человек пришёл к нему сам. Отражение контраста мощнее любого вывода извне — он не вызывает сопротивления.","ex":"«Ты едешь когда надо. А тебе даже не отвечают. Разница ощутимая.»"},{"s":"Руслан: «Получил повышение. Все поздравляют, а я жду когда разоблачат. Макс работает лучше, Лена умнее. Мне повезло. Или руководство ошиблось».","o":[{"t":"Назови вторичную боль","e":"Вторичная боль — боль от своей реакции. У Руслана первичная — страх разоблачения.","g":"Не та эмоция"},{"t":"Эхо с удивлением","e":"Повторить его слова с удивлением — не объяснять, не лечить. Добавить одно слово — каково это.","g":"Работает","ok":1},{"t":"Не спорь с внутренним голосом","e":"Точный метод для самозванца. Но эхо первее — называет каково жить с таким голосом.","g":"Следующий шаг"},{"t":"Сними стыд за чувство","e":"Руслан не стыдится тревоги — он боится разоблачения. Разные переживания.","g":"Не тот механизм"}],"m":"Эхо с удивлением — форма точного эмпатического отражения (Rogers) с добавлением живого отклика. При синдроме самозванца (Clance & Imes) человек изнутри не чувствует абсурда своей позиции. Эхо возвращает взгляд со стороны без спора: не «ты не прав», а «послушай как это звучит».","ex":"«Повысили — а ты сидишь и ждёшь когда скажут \"ошибочка вышла\"? Руслан, ну это же мучительно.»"},{"s":"Ева ночью: «Тревога без причины. Ничего не случилось, а внутри сжимает. И бесит что не могу объяснить. \"Из-за чего тревожишься?\" — \"Не знаю\". Звучит тупо».","o":[{"t":"Назови чувство","e":"Ева уже знает что чувствует тревогу. Проблема не в названии.","g":"Поверхностно"},{"t":"Признай раздвоенность как норму","e":"У Евы нет раздвоенности. Есть одно чувство и невозможность его объяснить.","g":"Не тот контекст"},{"t":"Убери требование объяснить","e":"«Из-за чего?» — когнитивный запрос в момент кризиса. Убрать необходимость оправдываться — уже валидация.","g":"Работает","ok":1},{"t":"Сними стыд за чувство","e":"Стыд есть — «звучит тупо». Но он за невозможность объяснить. Убрать требование точнее.","g":"Близко"}],"m":"Тревога часто не имеет когнитивного содержания — это активация нервной системы без чёткого триггера. Вопрос «из-за чего?» предполагает что у эмоции обязана быть причина. В DBT (Linehan) признание переживания без объяснения снимает когнитивный фильтр и даёт эмоции право быть.","ex":"«Мне плохо и не знаю почему — не значит что выдумываю. Тревога без причины — тоже тревога.»"},{"s":"Саша после ссоры: «Опять сорвался из-за ерунды. Жена просто спросила про ужин, а я начал орать. Какой же мудак. Она не заслуживает такого».","o":[{"t":"Отдели поступок от личности","e":"«Сорвался» — действие. «Мудак» — приговор. Разделить — открыть пространство для рефлексии.","g":"Работает","ok":1},{"t":"Сними стыд за чувство","e":"У Саши не стыд за чувство, а ярлык на себя как личность. Разные процессы.","g":"Не тот механизм"},{"t":"Назови оба чувства одновременно","e":"Два чувства есть. Но центральная проблема — что он слил поступок с собой.","g":"Не центральное"},{"t":"Назови чувство","e":"Саша уже знает что чувствует. Ему нужно разделение действия и идентичности.","g":"Поверхностно"}],"m":"В когнитивной терапии (Beck) это работа с глобальным негативным ярлыком — когнитивная ошибка сверхобобщения: «я сорвался» → «я мудак». Пока поступок слит с личностью, рефлексия невозможна: человек не анализирует что произошло, а наказывает себя за то кто он есть.","ex":"«Я не мудак — я устал и не справился. Разные вещи.»"},{"s":"Роман: «Похоронили отца во вторник. Телефон разрывается: \"держись\", \"крепись\", \"если что — звони\". Я смотрю на эти сообщения и не понимаю, что отвечать. Вчера пришёл брат, мы три часа просидели на кухне, почти молча. Впервые за неделю стало чуть легче».","o":[{"t":"Останься рядом без слов","e":"Он сам говорит, от чего полегчало: три часа на кухне почти молча. Брат уже показал метод, осталось повторить.","ok":1},{"t":"Назови чувство","e":"Что ему тяжело, видно и так. Назвать вслух значит опять требовать разговора, а разговоры его сейчас и душат."},{"t":"Предложи конкретную помощь","e":"«Если что — звони» он уже читал двадцать раз. Дела подождут. Запрос сейчас другой: чтобы кто-то был рядом."},{"t":"Назови необратимость","e":"Это словесный метод, а слова ему сейчас не заходят. Инструмент нормальный, время неподходящее."}],"m":"Первый уровень валидации по Линехан — присутствие: быть рядом и слушать, ничего не чинить. Алан Вольфельт, который учит сопровождению горюющих, называет это companioning: идти рядом с человеком в его горе, вместо того чтобы вести его куда-то. Молчание вдвоём часто помогает больше слов, потому что ничего не требует взамен, даже ответа.","ex":"«Я в субботу заеду. Могу просто посидеть, разговаривать необязательно.»"},{"s":"Костя после развода зовёт разбирать квартиру: «Забирай кофемашину, мне одному столько техники ни к чему. Да нормально всё, я даже выдохнул. Ну давай, за новую жизнь». Это третий тост за новую жизнь. Кофемашину, которую они с женой полгода выбирали, он суёт тебе в руки вместе с коробкой.","o":[{"t":"Назови невысказанное — бережно","e":"Третий тост, и машинка, которую полгода выбирали вдвоём, суётся в руки. Сказать можно тихо и один раз: если под «нормально» есть что-то ещё, я рядом. И не настаивать.","ok":1},{"t":"Поддержи оптимизм","e":"«Я даже выдохнул» — это оборона. Подыграть значит оставить его одного за этой обороной."},{"t":"Эхо с удивлением","e":"Эхо возвращает сказанное, а сказано «нормально». Получится поддакивание фасаду."},{"t":"Спроси в лоб: «тебе плохо?»","e":"В лоб значит заставить либо признаться, либо соврать. Второе вероятнее, и дверь закроется."}],"m":"Третий уровень по Линехан — озвучить то, что человек чувствует, но не говорит. Здесь всё решает подача: не диагноз («да тебе же плохо»), а открытая дверь («захочешь рассказать по-настоящему — я тут»). Без права промолчать этот метод превращается во вскрытие чужой защиты.","ex":"«Кофемашину беру. И слушай, если когда-нибудь захочется рассказать не \"нормально\", а как есть, — говори в любое время. Всё, наливай.»"},{"s":"Яна: «Новый парень в пятницу задержался на два часа, телефон сел. Я за эти два часа успела прожить всё: как он врёт, как я снова \"ничего не замечала\", как собираю коробки. Он приехал с цветами и не понял, почему я с ним не разговариваю. Я же знаю, что это из-за бывшего. Знаю. А трясёт всё равно».","o":[{"t":"Валидируй через историю","e":"Объяснять ей ситуацию не надо, она сама всё разложила. Ей нужно услышать: после двух лет вранья такая тряска — ожидаемая работа памяти.","ok":1},{"t":"Назови чувство","e":"Она называет всё сама, точнее некуда. Ещё раз назвать — ничего не добавить."},{"t":"Отдели поступок от личности","e":"Метод для тех, кто казнит себя за сделанное. Яна ничего не сделала, она два часа боялась."},{"t":"Убери требование объяснить","e":"Никто с неё объяснений не требует. Она объясняет сама и первая."}],"m":"Четвёртый уровень по Линехан: показать, что чувство логично вытекает из истории человека. Реакция, которая выглядит чрезмерной для ситуации, обычно ровно по размеру прошлого опыта. Когда «учитывая, что ты прожила, это ожидаемо» звучит вслух, уходит вторая боль — стыд за собственную реакцию.","ex":"«Тебе два года врали, и ты узнала последней. Конечно два часа тишины запускают в голове всё старое кино. Память так устроена.»"},{"s":"Кристина, шёпотом, пока дети в ванной: «В субботу они орали дуэтом почти час, и я поймала себя на том, что представляю: выхожу, сажусь в машину и еду. Без вещей, без плана. Просто еду. Потом младший обнял меня мокрыми руками, и мне стало так стыдно за эту машину, что я потом полночи лежала и прокручивала».","o":[{"t":"Нормализуй как общечеловеческое","e":"Фантазия про уехать после часа ора — стандартная реакция перегретой психики. Когда она услышит, что так бывает у всех на пределе, ярлык «я плохая мать» начнёт отклеиваться.","ok":1},{"t":"Валидируй через историю","e":"Работает, когда чувство растёт из личного прошлого. Тут прошлое ни при чём, при чём час ора."},{"t":"Назови двойной удар","e":"Второй удар она наносит себе сама, стыдом. Снимается он как раз нормализацией."},{"t":"Предложи контакт","e":"Обнять можно. Но на вопрос «нормальная ли я» объятие не отвечает."}],"m":"Пятый уровень по Линехан — нормализация: «на твоём месте так почувствовал бы кто угодно». Снимает стыд за чувства, которые человек считает запретными. Нормализуется чувство и фантазия, про действие речи нет. И это не отмашка «у всех так, расслабься»: тяжесть, из которой чувство выросло, признаётся отдельно.","ex":"«Час ора дуэтом — любой живой человек мысленно уже на трассе. Ты никуда не уехала, ты домыла им ванну. Вот тебе и ответ, какая ты мать.»"},{"s":"У Артура лимфома, лечится, прогноз рабочий. «Знаешь, что бесит больше химии? Все теперь говорят со мной, как диктор в планетарии. Медленно, бережно. Лучший друг на днях полчаса мялся, прежде чем рассказать, что у него машина сломалась. Боялся грузить. У меня рак, а не хрусталь».","o":[{"t":"Говори как с равным","e":"Он сам сформулировал: рак, а не хрусталь. Обычные новости, обычные жалобы, обычные подколки. Так он остаётся человеком, а не диагнозом.","ok":1},{"t":"Назови чувство","e":"Можно, но есть риск сделать это тем же голосом диктора. Он просит не слов о себе, а прежний тон."},{"t":"Признай телесный сигнал","e":"Про тело он не говорит. Говорит про то, как с ним разговаривают."},{"t":"Сними стыд за чувство","e":"Стыда в его словах нет. Есть злость на планетарий вокруг."}],"m":"Шестой уровень по Линехан — радикальная искренность: держаться с человеком как с равным, без специального щадящего режима. Бережный тон, которого он не просил, каждый раз сообщает ему, что он теперь другой. Обычное обращение, включая жалобы на сломанную машину, возвращает его в число живых.","ex":"«Слушай, у меня бойлер потёк, сейчас всё это на тебя вывалю, готовься. И в субботу шахматы, ты обещал реванш. Болезнь не отмазка.»"},{"s":"Дина на шестом месяце: «Мы три года этого хотели. А я лежу ночью, смотрю в потолок и думаю: вдруг я не смогу её любить? Все вокруг светятся, спрашивают, счастлива ли я. Говорю \"конечно\". Один раз попробовала загуглить \"не чувствую радости беременность\" и стёрла запрос, как будто преступление гуглила».","o":[{"t":"Признай раздвоенность как норму","e":"Хотели три года, и страшно до потолка. Ей нужно услышать, что оба факта настоящие и один другого не отменяет. Тогда «конечно» перестанет быть враньём себе.","ok":1},{"t":"Нормализуй как общечеловеческое","e":"Соседний метод, но «все боятся» смазывает её конкретный узел: ждёт, и при этом не чувствует того, что вроде положено."},{"t":"Назови чувство","e":"Их два, и они тянут в разные стороны. Выбрать одно для называния значит подыграть половине."},{"t":"Убери требование объяснить","e":"Требований извне нет, «конечно» она говорит сама. Дело в праве на второе чувство, а не в отчётности."}],"m":"Одновременные противоположные чувства к чему-то важному — обычное устройство психики. Диалектический подход (в DBT это прямо в названии) не заставляет выбирать между чувствами: признаются оба сразу, «и жду, и боюсь». Само требование выбрать одно правильное чувство и производит ощущение «со мной что-то не так».","ex":"«Ты её три года ждёшь, и тебе страшно. Так бывает у людей сплошь и рядом, одно другому не мешает. И запрос свой можешь гуглить спокойно, за это не сажают.»"},{"s":"Никита: «Не добрал четыре балла на экзамене в ординатуру. Полгода жил по будильнику на шесть, отписался от всего, к друзьям не ходил. Позвонил отцу, он выслушал и сказал: \"Значит, недоготовился\". Я положил трубку и сижу. Может, он прав? Может, я правда мог лучше?»","o":[{"t":"Признай усилие, а не результат","e":"Отцовская фраза стёрла полгода будильников одним словом. Пока кто-то не вернёт эти полгода на место, «может, он прав» будет разъедать дальше.","ok":1},{"t":"Эхо с удивлением","e":"Эхо высветило бы дикость фразы, но Никита уже наполовину на стороне отца. Сначала вернуть факты."},{"t":"Отдели поступок от личности","e":"Он не винит себя за поступок. Он сомневается, считаются ли его полгода."},{"t":"Назови двойной удар","e":"Удар и правда двойной, но это описание. На «может, я мог лучше» отвечает признание сделанного."}],"m":"Кэрол Дуэк показала на школьниках: когда оценивают только результат, один провал перечёркивает весь процесс, и человек перестаёт видеть собственную работу. Признание усилия возвращает стёртые факты на место: полгода подъёмов в шесть были, четыре балла их не отменяют.","ex":"«Погоди. Полгода подъёмов в шесть — были. Отказался от всего — было. Четыре балла — это про экзамен. Про то, как ты готовился, они ничего не говорят.»"},{"s":"Степан: «У коллеги месяц назад умерла мама. Мы всем отделом скидывались, я её подменял. А у меня развод идёт, сплю часа по три, на обеде сижу в машине, чтобы ни с кем не разговаривать. Рассказать никому не могу. У человека мама умерла, а я тут со своим разводом полезу. Стыдно даже сравнивать».","o":[{"t":"Убери иерархию боли","e":"Он сам вычеркнул себя из очереди на сочувствие: «стыдно даже сравнивать». Пока боль стоит в очереди по тяжести, три часа сна так и остаются ерундой.","ok":1},{"t":"Назови чувство","e":"Что ему плохо, он знает. Застряло другое: «не имею права». С правом и надо работать."},{"t":"Нормализуй как общечеловеческое","e":"«Люди и не такое переживают» — он этой нормализацией себя и глушит. Есть риск подлить того же."},{"t":"Назови изоляцию как отдельный слой","e":"Обед в машине — изоляция, да. Но она следствие запрета. Начинать с причины."}],"m":"Брене Браун называет это comparative suffering, сравнительное страдание: внутренняя бухгалтерия, где сочувствие положено только за достаточно крупное горе. Бухгалтерия врёт в обе стороны: чужому горю от твоего молчания легче не становится. А твоё в тишине растёт. Сочувствия хватает на всех, делить его не нужно.","ex":"«У неё горе. И у тебя горе. Сочувствие не торт, чтобы его делить. Три часа сна месяц подряд — это серьёзно, приходи, поговорим.»"}],"cn":"Здесь мы тренируем не «что сказать», а «как подойти». Это уровень стратегии: назвать чувство, снять стыд, признать масштаб потери, нормализовать реакцию — это разные инструменты. Задача — выбрать тот, который точнее всего попадает в ситуацию."}],"en":[{"id":"validate","tt":"Validate","ds":"Pick the validating response","sm":"c","ins":["Read the situation","Pick the validating response out of four","A wrong answer will show why it doesn't fit"],"dt":[{"s":"Rachel texts the group chat:\n\"Jess cancelled on me again. Third time this month. Didn't even really apologize, just 'oh sorry, can't.' I don't even know why I bother making plans.\"","o":[{"t":"Rachel, three times in a row — that's really hurtful. And without even a real apology — that makes it worse.","e":"Names the feeling (hurt), reflects the situation, no advice.","g":"Validation","ok":1},{"t":"Maybe Jess is just swamped at work? Try not to take it personally — she probably didn't mean it.","e":"Defends Jess, asks Rachel not to feel hurt — bans the feeling.","g":"Feeling ban"},{"t":"Honestly, if she keeps doing that, just stop inviting her. Why do you need a friend like that?","e":"Unsolicited advice — decides for Rachel instead of supporting her.","g":"Advice"},{"t":"Same thing happened to me with Holly, remember? Everyone does it sometimes, just let it go.","e":"Shifts to self, dismisses through 'everyone does it.'","g":"Dismissal"}]},{"s":"Sophie (age 6) comes home from kindergarten, crying:\n\"Megan said she won't be my friend anymore! And everyone went to play with her, and I sat all alone!\"","o":[{"t":"Oh sweetie, don't cry! Megan will forget about it by tomorrow, and you'll play together again.","e":"Denies the feeling, promises something she can't guarantee.","g":"Dismissal"},{"t":"Did you ask Megan why? Maybe you did something and she got upset with you?","e":"Shifts blame onto the child, forces her to justify herself.","g":"Blame"},{"t":"You're upset that Megan said that. And sitting alone while everyone else plays — that's really sad. I get it.","e":"Names both feelings (hurt + sadness), reflects the situation.","g":"Validation","ok":1},{"t":"It's no big deal, honey! You have plenty of friends. Tomorrow you'll play with Paige, everything will be fine!","e":"Minimizes the pain, redirects to positivity.","g":"Distraction"}]},{"s":"Daisy after a job interview:\n\"Third rejection in a row. I prepared for each one: researched the company, did take-home assignments. They don't even give feedback, just 'you're not the right fit.' I'm starting to think something is wrong with me.\"","o":[{"t":"Three is nothing, seriously. I had 15 rejections when I was job hunting. Just keep going, you'll find the right one!","e":"Compares to self, minimizes through statistics.","g":"Dismissal"},{"t":"Maybe you should ask for feedback? Or show your resume to an HR specialist? That way you'll know what to improve.","e":"Jumps to solutions, doesn't acknowledge the feeling.","g":"Advice"},{"t":"There's nothing wrong with you, Daisy. The market is tough, competition is insane. You'll make it, I believe in you!","e":"Denies doubt instead of acknowledging the pain.","g":"Cheerful denial"},{"t":"Wait — three times in a row and they didn't even tell you why? That's just...","e":"Echo with surprise. The unfinished sentence shows words aren't enough.","g":"Validation","ok":1}]},{"s":"Cara, quietly:\n\"Whiskers died yesterday. 14 years together. At work everyone's like: 'It's just a cat, get a new one.' As if she were a thing you can replace.\"","o":[{"t":"I'm sorry, Cara. But you know, maybe it really would help to get a kitten? It helps with the grieving.","e":"Repeats the same dismissal as her coworkers, just softer.","g":"Advice"},{"t":"I get it, my dog died too. Time heals, trust me, in a month you'll feel better.","e":"Shifts to self, makes baseless promises.","g":"Hijacking"},{"t":"14 years — that's a huge part of your life. Of course the pain of this loss runs deep.","e":"Acknowledges the scale of the loss, legitimizes the depth of pain.","g":"Validation","ok":1},{"t":"They don't mean any harm, they just don't know what to say. Try not to be upset with them — they've probably never had a pet.","e":"Justifies those who dismissed her, asks her not to be upset.","g":"Defending offenders"}]},{"s":"Jess, in Berlin:\n\"Six months here and zero friends. Everyone at work is polite, but nothing goes beyond 'Hi, how are you.' Every evening I sit alone, watch Russian shows, and cry.\"","o":[{"t":"Six months isn't that long, give it time. Sign up for yoga or a class — you'll definitely meet someone.","e":"Minimizes the duration, gives advice instead of support.","g":"Advice"},{"t":"Sitting alone every evening in a foreign country — that's a piercing kind of loneliness. And crying because of it makes total sense.","e":"Names the feeling, normalizes the reaction, no advice.","g":"Validation","ok":1},{"t":"But you're the one who wanted to move, remember? Think about why you started this and hang in there!","e":"Reminds her of her choice as an argument against her feelings.","g":"Reproach"},{"t":"Have you tried Russian-speaking groups? Berlin has tons of them, WhatsApp chats everywhere. You'll find your people fast.","e":"Solves the problem instead of acknowledging pain.","g":"Advice"}]},{"s":"Erin shares:\n\"I told Josh it hurt that he didn't call when I was sick. And he said: 'You're being dramatic again. I was busy. Stop making a scene.'\"","o":[{"t":"Maybe he really was swamped? Men show care differently. Try explaining it to him more calmly.","e":"Justifies Josh, asks Erin to change.","g":"Defending offender"},{"t":"You two need a serious talk when you've both cooled down. Tell him how much those words hurt. He needs to hear it.","e":"Jumps to an action plan.","g":"Advice"},{"t":"That's a red flag, Erin. If he reacts like this now, it'll only get worse. Think about whether you need someone like that.","e":"Judges the relationship instead of acknowledging feelings.","g":"Verdict"},{"t":"Wait — you came to tell him you were hurt, and he called it 'making a scene'? That's a double blow — first he didn't call, then he dismissed you on top of it.","e":"Names the mechanism (double blow). Not in a therapist's tone, but through retelling.","g":"Validation","ok":1}]},{"s":"Marina, in a whisper:\n\"My best friend got promoted. I smiled, congratulated her. Cried at home. Not because I'm not happy for her. But because I'm jealous. And disgusted with myself — what kind of person does that make me?\"","o":[{"t":"Jealousy is normal, everyone feels it. The important thing is you're happy for her — that says something good about you.","e":"Minimizes through 'everyone does it.' Focuses on the positive instead of the pain.","g":"Dismissal"},{"t":"Being happy and jealous at the same time doesn't make you a bad person. It makes you a real one.","e":"Acknowledges both feelings simultaneously, lifts the shame.","g":"Validation","ok":1},{"t":"Maybe jealousy is a signal that you need to grow too? Use it as motivation — that's a healthy approach.","e":"Turns the feeling into a task, ignores the shame.","g":"Reframe"},{"t":"If it bothers you that much, maybe it's worth figuring out what you're missing yourself. A therapist could help.","e":"Sends to a specialist instead of acknowledging.","g":"Advice"}]},{"s":"Owen:\n\"I read Megan's texts with her ex. I know I shouldn't have snooped. But there was 'I miss our trips,' smiley faces. Can't look at her, but can't say anything either — it's my fault for snooping.\"","o":[{"t":"You did a crappy thing — and you know it. But seeing 'I miss you' — that's genuinely painful. One doesn't cancel the other.","e":"Doesn't excuse, but validates the feeling. Acknowledges both facts.","g":"Validation","ok":1},{"t":"What did you expect, going through someone's phone? You broke her trust. Talk to her honestly, stop keeping it in.","e":"Piles on guilt, gives advice.","g":"Reproach + advice"},{"t":"Lots of people stay friends with exes — that conversation means nothing. Don't overthink it.","e":"Dismisses what he saw, asks him to stop worrying.","g":"Minimization"},{"t":"If she misses her ex, maybe something's lacking with you. Time for a serious conversation about your relationship.","e":"Speculates about motives, shifts away from Owen's feeling.","g":"Interpretation"}]},{"s":"Tanya:\n\"Grandma is in the hospital. Mom goes every day, but I can't. Work, kids, no energy left. Grandma says: 'It's fine, don't come.' But I know she's struggling. And I know I'll regret it later.\"","o":[{"t":"Find at least one day, Tanya. You'll regret it later. Seriously, you'll never forgive yourself, trust me.","e":"Amplifies the guilt instead of supporting.","g":"Guilt pressure"},{"t":"You're doing what you can — calling, thinking about her. Don't blame yourself, Grandma understands.","e":"Denies the guilt instead of acknowledging the trap.","g":"Cheerful comfort"},{"t":"Go — and there's no energy left. Don't go — and the guilt will eat you alive. Neither option feels okay.","e":"Names the trap — retells the reality without interpretation.","g":"Validation","ok":1},{"t":"Hire a caregiver or ask your mom to set up a video call. At least you'll 'be there' somehow.","e":"Solves the problem instead of acknowledging it.","g":"Advice"}]},{"s":"Ryan:\n\"Got promoted. Everyone's congratulating me, but I'm waiting for them to say it was a mistake. Max works harder, Lena is smarter. I just got lucky. Or management messed up.\"","o":[{"t":"You got promoted for a reason! You're a great specialist — stop putting yourself down, celebrate for once!","e":"Denies the experience, demands happiness.","g":"Cheerful denial"},{"t":"That's impostor syndrome — lots of people go through it. Read about it — once you see the pattern, it gets easier.","e":"Slaps a label instead of acknowledging the feeling.","g":"Diagnosis"},{"t":"Since they promoted you, they clearly see potential. It's not for you to decide who's better — management already decided.","e":"Argues instead of supporting.","g":"Logic"},{"t":"You got promoted — and you're sitting there waiting to hear 'sorry, wrong person'? Ryan, that must be agonizing.","e":"Echo with surprise. Returns his words, adds just one thing — 'agonizing.'","g":"Validation","ok":1}]},{"s":"Josh after a fight:\n\"Lost it again over nothing. My wife just asked about dinner and I started yelling. What an awful person I am. She doesn't deserve this.\"","o":[{"t":"I snapped — and I feel terrible about it. That means I care. I'm not a terrible person — I was exhausted and lost control. Those are different things.","e":"Separates the act from identity. 'Feeling terrible' = I care about us.","g":"Self-validation","ok":1},{"t":"I'm awful and always will be. She'll leave, and she should. I ruin everything I touch.","e":"Catastrophizing, verdict instead of analysis.","g":"Self-punishment"},{"t":"Everyone yells sometimes, it's not a big deal. She's used to it. I'll buy flowers tomorrow and we'll move on.","e":"Dismisses both his guilt and his wife's feelings.","g":"Minimization"},{"t":"I need to learn to control my emotions. I'll sign up for therapy, start meditating, become better.","e":"Jumps to solutions, skipping acknowledgment.","g":"Escape plan"}]},{"s":"Tim:\n\"Max posted: 'Quit my job, started a company, first million in six months.' 500 likes. But I know he's in debt and his wife left. Everyone's commenting 'legend.' And I feel disgusted and jealous at the same time.\"","o":[{"t":"You know the truth! Why be jealous? Max is actually doing terribly. You're in a better position.","e":"Jealousy is irrational — 'knowing the truth' doesn't cancel the feeling.","g":"Rationalization"},{"t":"Delete social media, seriously. Life is so much better without it. All the showing off — pure poison.","e":"Unsolicited advice instead of acknowledgment.","g":"Advice"},{"t":"You know it's all fake — and you're still jealous. Plus it's infuriating that everyone buys it. Both things at once — and you're not even sure who you're angrier at: him, them, or yourself.","e":"Names the contradiction, doesn't try to resolve it.","g":"Validation","ok":1},{"t":"Max is Max, you are you. Don't compare. Your path isn't any worse — everyone has their own journey.","e":"Forbids a comparison that already happened.","g":"Cliché"}]},{"s":"Mikey (age 8) before school:\n\"I don't want to go. Vic will call me names again. Yesterday he told everyone I'm stupid. The teacher didn't hear.\"\n(Fists clenched, eyes wet.)","o":[{"t":"I'll talk to the teacher, don't worry. Vic won't do it anymore, I promise — everything will be fine.","e":"Promises something he can't guarantee.","g":"False promise"},{"t":"You're angry and it hurts — he did it in front of everyone, and nobody helped. That's not fair.","e":"Names both feelings (anger + pain), acknowledges the injustice.","g":"Validation","ok":1},{"t":"Say something back! Don't let him push you around. You can stand up for yourself — come on, be tough!","e":"Demands fighting back, ignores the pain.","g":"Pressure"},{"t":"Vic is probably unhappy himself — happy kids don't act that way. Just ignore him, he's just showing off.","e":"Explains the bully's behavior instead of acknowledging Mikey's feelings.","g":"Reframe"}]},{"s":"Greg:\n\"Panic attacks. Heart pounding, hands shaking, feels like I'm dying. I told my mom, and she said: 'It's from your phone — go take a walk.' Friends say: 'You think too much.' Like I'm making it up.\"","o":[{"t":"Have you seen a doctor? Panic attacks are treatable. Therapy, sometimes medication — it gets much easier.","e":"Jumps to solutions.","g":"Advice"},{"t":"Try breathing exercises: inhale 4, hold 7, exhale 8. It really helped me when I had bad anxiety.","e":"Gives a technique instead of acknowledgment.","g":"Recipe"},{"t":"Your mom doesn't get it — older generations were raised differently. Don't be upset, she really doesn't mean any harm.","e":"Justifies Mom, asks him not to be upset.","g":"Defending offender"},{"t":"You told your mom, you told your friends — and you're still alone with this. That's incredibly lonely.","e":"Focus on isolation as a separate layer of suffering on top of the attacks themselves.","g":"Validation","ok":1}]},{"s":"Jen, in a whisper:\n\"Every kid in my daughter's class has an iPhone. She asked for one. We can't afford it. I bought an Android. She said 'thanks,' but I saw how disappointed she was. I feel like a bad mom — I can't give her what everyone else has.\"","o":[{"t":"\"I feel like a bad mom\" — that's so heavy to carry. Especially when you're doing everything you can.","e":"Acknowledges the weight of the guilt itself.","g":"Validation","ok":1},{"t":"An iPhone doesn't measure love, Jen. You gave what you could. She'll grow up and be grateful.","e":"Denies the guilt instead of acknowledging it.","g":"Comfort"},{"t":"Get it on a payment plan or wait for a sale. There are options — doesn't have to be brand new.","e":"Solves the problem instead of supporting.","g":"Advice"},{"t":"Don't raise a consumer, Jen. Let her learn to appreciate what she has. It'll be good for her.","e":"Turns the situation into a parenting lesson.","g":"Moralizing"}]},{"s":"Paige after her thesis defense:\n\"Got an A. Everyone's congratulating me, Mom's crying. And I'm thinking: the committee went easy. If they'd been stricter, I would've failed. Can't even feel happy. What's wrong with me?\"","o":[{"t":"You got an A! That's an objective assessment! Stop overthinking it and let yourself be happy for once!","e":"Demands happiness, denies the experience.","g":"Cheerful denial"},{"t":"Not being able to feel your own success — that's really hard.","e":"Names the secondary pain — the inability to feel her own achievement.","g":"Validation","ok":1},{"t":"That's classic impostor syndrome — look it up. When you see it as a pattern, it gets easier.","e":"Slaps a label instead of acknowledging.","g":"Diagnosis"},{"t":"Everyone feels that way sometimes. I thought the same after my exams. It'll pass, don't worry.","e":"Dismisses through 'everyone does it,' promises it'll pass.","g":"Minimization"}]},{"s":"Stas, living in Amsterdam:\n\"Here I'm 'the Russian.' Back home: 'You're not one of us anymore, Mr. European.' I don't belong anywhere. At the office party I don't get the jokes. When I call Mom, she says 'we got snow here,' and I feel like a traitor... because I outgrew the place I left.\"","o":[{"t":"There you're Russian, here you're European — and everywhere, a little bit foreign. It's not that you don't fit in. It's just a very uncomfortable place you're in right now.","e":"Reflects the split without judgment, lifts the personal blame.","g":"Validation","ok":1},{"t":"You didn't betray anyone, you're just living your life. You'll find balance over time — lots of people go through this.","e":"Denies the feeling of betrayal, promises balance.","g":"Comfort"},{"t":"Normal for expats. The first couple of years are always like this. You'll find your crowd, and it'll get easier.","e":"Dismisses through 'everyone does it,' makes a forecast.","g":"Minimization"},{"t":"Visit home more often or find a Russian-speaking community in Amsterdam. It'll help you feel like you belong.","e":"Solves the problem instead of acknowledging.","g":"Advice"}]},{"s":"Nadia, quietly:\n\"Miscarriage. 8 weeks. We hadn't told anyone yet. So now I'm grieving, and it's a regular day for everyone else. A friend said: 'Well, 8 weeks — that's not really a baby yet.' Then I cried in the bathroom for an hour.\"","o":[{"t":"Your friend didn't mean to hurt you. People don't know what to say in these moments. She just doesn't understand.","e":"Justifies the friend, leads away from Nadia's pain.","g":"Defending offender"},{"t":"It happens a lot at early stages — the body just doesn't let it develop. Next time it'll work out, don't lose hope.","e":"Repeats the same dismissal in a different form.","g":"Minimization"},{"t":"You lost a baby. Not '8 weeks,' not 'too early.' A baby. You have every right to grieve.","e":"Names the loss directly, protects the right to grieve.","g":"Validation","ok":1},{"t":"I'm sorry, Nadia. You're strong, you'll get through this. Maybe talking to a therapist who specializes in loss would help.","e":"Comfort + referral to specialist instead of acknowledgment.","g":"Advice"}]},{"s":"Caleb, 19 years old:\n\"My parents want me to become a lawyer like my dad. I want to pursue music. I signed up for a production course. Mom found out — hasn't spoken to me in two days. Dad: 'Do what you want, but don't come complaining later.' Like they gave me freedom and punished me for it at the same time.\"","o":[{"t":"Think about it realistically: music is unstable. Maybe combine them? A law degree is a solid backup.","e":"Takes the parents' side.","g":"Advice"},{"t":"Mom's silent, Dad 'allowed' it — but with a threat. 'Do what you want, but don't complain' — that's not freedom, Caleb. That's punishment.","e":"Names the trap directly. Renames it: not 'permission,' but a trap.","g":"Validation","ok":1},{"t":"That's their fear, not your problem. Live your life — they'll get used to it. All parents are against it at first.","e":"Dismisses the pain through 'everyone does it.'","g":"Minimization"},{"t":"I support you, Caleb! Music is awesome. Believe in yourself, you'll make it — I'm sure you're talented!","e":"Supports the decision but doesn't acknowledge the feelings.","g":"Supporting action"}]},{"s":"Holly, 31, Amsterdam:\n\"Dad got diagnosed. Not fatal, but serious. Mom says 'don't come, everything's fine' — but I can hear how exhausted she is. Flights cost a month's salary. And the visa — not sure I'd be let back in. So I sit here, work, pay taxes, go to yoga. I just want to be there. And I can't.\"","o":[{"t":"You can't drop everything and go — that's not rational. Doctors will help your dad, and neighbors will help your mom.","e":"Argues instead of acknowledging.","g":"Logic"},{"t":"Start saving for flights, maybe ask friends for help. And with the visa — sometimes lawyers can find a way.","e":"Solves the problem instead of supporting.","g":"Advice"},{"t":"They're telling you everything's fine. Trust them — they'll manage.","e":"Takes the facade at face value.","g":"Minimization"},{"t":"Mom says 'don't come' — but you hear something else. And you can't go, and you can't stop thinking about it.","e":"Names the contradiction, acknowledges the impossible trap.","g":"Validation","ok":1}]},{"s":"Dan, 38:\n\"My son hasn't called in two years. I know it's my fault. The divorce was ugly, I said things I shouldn't have. Later I tried to make up — he won't pick up. My ex says it was his decision, not hers. Maybe so. I look at his photos — he's different now. I missed it.\"","o":[{"t":"Don't give up — keep writing letters, leaving messages. Kids always come back to their parents eventually.","e":"Promises what can't be guaranteed.","g":"False promise"},{"t":"You admit you're to blame. Then you need to work on yourself — see a therapist, change. Then your son will see it.","e":"Jumps to a plan, ignores the pain.","g":"Advice"},{"t":"You look at his photos — and he's already different. You missed that, and you know it. Carrying that silently is incredibly hard.","e":"Names the specific pain — irreversibility.","g":"Validation","ok":1},{"t":"Your ex might have influenced him — kids at that age are easily swayed. Don't blame yourself so much.","e":"Shifts blame, denies his guilt.","g":"Defense + minimization"}]},{"s":"Holly scrolling Instagram:\n\"Friend posted a photo from Bali: husband, kid, ocean. And I'm in a rented studio, post-divorce, with a loan. Feeling angry at her.\"","o":[{"t":"I'm jealous and petty. She didn't do anything to me. I should delete Instagram and stop comparing.","e":"Condemns herself for the feeling.","g":"Self-punishment"},{"t":"I don't care about her Bali. Everyone lives how they want. I have my own path and I'm not ashamed of it.","e":"Blocks the feeling with bravado.","g":"Denial"},{"t":"Enough scrolling — I'll focus on my own life. Anger is energy — I'll channel it into something useful.","e":"Turns it into a task, doesn't acknowledge the pain.","g":"Reframe"},{"t":"I'm angry at her — but it's not about her. Her photo just hit exactly where it hurts right now.","e":"Lifts the blame for anger, names the mechanism.","g":"Self-validation","ok":1}]},{"s":"Lisa:\n\"Spent three hours listening to how great Kate's life is. And the moment I started talking about my stuff, she went: 'oh, gotta run, let's catch up soon!' And left.\"","o":[{"t":"Wait — three hours you listened to her, and when it was your turn — 'gotta run'? Seriously? How did that make you feel?","e":"Repeats the contrast with indignation, then asks a question.","g":"Validation","ok":1},{"t":"Maybe she really had to go. Not everyone notices these things. Next time, start with yourself first.","e":"Justifies Kate, gives advice.","g":"Defense + advice"},{"t":"I know the type. I had a friend like that — only about herself. Stopped calling her and honestly, it was a relief.","e":"Shifts to self.","g":"Hijacking"},{"t":"Maybe Kate isn't the right person for those conversations? Find someone who knows how to listen — not everyone is like that.","e":"Solves instead of acknowledging.","g":"Advice"}]},{"s":"Philip, quietly:\n\"Weird thing — I'm technically fine. Nothing hurts, nothing happened. But I come home from work and just lie down. Every day. Wife asks 'what's wrong' — and I don't know what to say. Nothing, I guess.\"","o":[{"t":"Maybe you just need a proper rest? Take a vacation, go somewhere — you'll come back a different person.","e":"Offers a solution, doesn't acknowledge the state.","g":"Advice"},{"t":"Nothing happened — but there's no energy left. Sometimes that's even harder than when there's a clear reason.","e":"Legitimizes a state without an obvious cause.","g":"Validation","ok":1},{"t":"Philip, that sounds like depression. See a doctor, seriously. Therapy and medication can really help these days.","e":"Slaps a label, sends to a doctor.","g":"Diagnosis"},{"t":"Maybe it's time to change jobs? Doing the same thing every day — of course it's draining. Think about what you actually want from life.","e":"Interprets the cause, gives advice.","g":"Advice"}]},{"s":"Eva, late at night:\n\"Anxiety for no reason. Nothing happened, but everything inside is clenched. And it's frustrating that I can't explain it. 'What are you anxious about?' — 'I don't know.' Sounds stupid.\"","o":[{"t":"Just anxiety — happens to everyone. Take a deep breath, have some tea, read a book — it'll pass. Don't spiral.","e":"Dismisses through 'happens to everyone,' gives a recipe.","g":"Minimization"},{"t":"Probably something from the past. You should see a therapist and figure out the root causes.","e":"Interprets, sends to a specialist.","g":"Advice"},{"t":"I feel bad and I don't know why. That doesn't mean I'm making it up. Anxiety without a reason is still anxiety. I don't owe anyone an explanation.","e":"Accepts causeless anxiety, lifts the shame.","g":"Self-validation","ok":1},{"t":"I'll stop thinking about it. The more I think, the worse it gets. Tomorrow is a new day — it'll pass, everything always does.","e":"Blocks the feeling, promises 'it'll pass.'","g":"Suppression"}]},{"s":"Elliot:\n\"Wired $3,000 to scammers. They called pretending to be the bank, I panicked, transferred it. When I realized, my hands were shaking. I told my wife, and she said: 'How could you fall for that?! Are you insane?'\"","o":[{"t":"Scammers these days are incredibly sophisticated — the pressure they put on you, anyone could fall for it. Don't blame yourself.","e":"Completely denies blame, minimizes.","g":"Comfort"},{"t":"$3,000 gone — that alone is a nightmare. And instead of 'I'm here for you,' you hear 'how could you?' That's a second blow, Elliot. You were deceived — you're not an idiot.","e":"Names the double blow. No advice, just seeing.","g":"Validation","ok":1},{"t":"File a police report and call the bank, ASAP. Sometimes the money is recovered. The key is to act fast.","e":"Jumps to action.","g":"Advice"},{"t":"Terrible, of course. But it's a lesson for the future: never transfer money over the phone. At least now you'll always know.","e":"Turns pain into a 'lesson.'","g":"Moralizing"}]},{"s":"Danny (age 10), quiet, avoiding eye contact:\n\"Dad, I don't want to go to soccer anymore. The coach yells, the kids laugh when I miss. I go there and my stomach hurts. But you wanted me to play...\"","o":[{"t":"Danny, everyone goes through this. It's tough for everyone at first! Give it another month — you'll get into it and start to like it.","e":"Dismisses through 'everyone does it,' pushes to continue.","g":"Minimization"},{"t":"Okay, if you don't want to, don't go. We'll find something else. Swimming, karate, whatever you want — your pick!","e":"Decides for the child, doesn't acknowledge feelings.","g":"Quick fix"},{"t":"I'll talk to the coach so he stops yelling. And I'll deal with the kids. Don't worry, it'll all be fine.","e":"Promises to fix everything, doesn't hear the child.","g":"False promise"},{"t":"Listen — your stomach hurting before practice, that's not about soccer. That's your body telling you it's hard. And that you told me instead of keeping it in — that matters, Danny.","e":"Connects body symptom to feeling, praises honesty.","g":"Validation","ok":1}]},{"s":"Stella, 29, inner monologue:\n\"Got an offer in Berlin. A good one. Nothing like this back home. But Mom just retired, my best friend's wedding is in June, my nephew is growing up — I barely see him as it is. If I leave, all of it becomes a phone. Photos. Voice messages. I want to be there in person. And I want Berlin too. Both at once. That's impossible.\"","o":[{"t":"Stella, offers like this don't wait. Your family will understand — you'll fly in for holidays, it's totally doable now.","e":"Pushes toward a decision, promises 'family will understand.'","g":"Advice"},{"t":"Then stay. Family is more important than a career — you won't regret it.","e":"Picks a side, doesn't see the trap.","g":"Oversimplification"},{"t":"Maybe the problem isn't that I can't choose. Maybe it's that both options cost something real.","e":"Reframes 'I can't' as 'there's something to lose either way.'","g":"Self-validation","ok":1},{"t":"This is your chance, Stella. Your nephew will grow up and understand. You only live once.","e":"Dismisses attachments for the sake of career.","g":"Pressure"}]},{"s":"Rita, 31, to a friend over coffee:\n\"He's good. Really. Caring, reliable, doesn't drink, doesn't cheat. Mom says 'he's a gem, hold on to him.' And I do. But when he walks into the room — nothing. Three years now. I think: maybe I'm broken. Maybe this is just how it is after three years. Maybe I'm just spoiled by movie romance.\"","o":[{"t":"Mom says hold on — and you're holding on. You're just not sure what exactly you're holding on to.","e":"Names the mechanical nature of 'doing the right thing.'","g":"Validation","ok":1},{"t":"Rita, passion fades for everyone. It's normal — what matters is respect and trust. You've just matured.","e":"Dismisses through 'happens to everyone.'","g":"Minimization"},{"t":"If you've felt nothing for three years — why torture yourself and him? You need to have an honest conversation.","e":"Pushes toward a decision instead of acknowledging.","g":"Advice"},{"t":"Maybe it's just boredom? Try something new — a trip, a shared hobby. Relationships take effort.","e":"Suggests a fix, doesn't acknowledge the void.","g":"Advice"}]},{"s":"Alina, to a friend:\n\"I'm always the one who reaches out first. I text, ask how they're doing, show up when things are bad. Last week I had a rough day — messaged one friend, then another. Both read it. One replied a day later: 'oh sorry, been crazy busy.' The other never replied at all.\"","o":[{"t":"People are just busy, Alina. Don't take it to heart — it doesn't mean they don't care. Just reach out again.","e":"Justifies, asks her not to be hurt.","g":"Minimization"},{"t":"You show up for your friends when they're struggling. And you can't even get a reply. The gap is real.","e":"Names the imbalance, concisely and precisely.","g":"Validation","ok":1},{"t":"Then they're not your real friends. Time to clean up your circle — if they don't reply, they're not worth it.","e":"Passes judgment instead of acknowledging pain.","g":"Verdict"},{"t":"Maybe you give too much? People get used to it. Try pulling back — see who stays.","e":"Blames Alina for being too caring.","g":"Advice"}]}]},{"id":"find_invalid","tt":"Find Invalidation","ds":"Spot the dismissive response","sm":"i","ins":["Read the situation","Find the one dismissive response among validating ones","The other three are genuine validation"],"dt":[{"s":"Marina whispers: \"My best friend got promoted. I smiled, congratulated her. Cried at home. Not because I'm not happy for her. But because I'm jealous. And disgusted with myself — what kind of person does that make me?\"","o":[{"t":"\"Jealousy is a signal. It means you want to grow too. Use it as motivation.\"","e":"Reframing. Doesn't acknowledge the feeling, immediately turns it into a task.","inv":1},{"t":"\"Being happy and jealous at the same time doesn't make you a bad person. It makes you a real one.\"","e":"Names both feelings without judgment."},{"t":"\"Feeling disgusted with yourself for being jealous — that's a separate kind of heaviness. Being ashamed of a feeling, on top of the feeling itself.\"","e":"Acknowledges shame as a separate layer."},{"t":"\"You smiled and congratulated her — and cried at home. That's a very lonely thing to carry inside.\"","e":"Names the loneliness."}]},{"s":"Josh after a fight: \"Lost it again over nothing. My wife just asked about dinner and I started yelling. What an awful person I am. She doesn't deserve this.\"","o":[{"t":"\"I snapped — and I feel terrible. That means I care.\"","e":"Acknowledges the pain and connects it to caring."},{"t":"\"'She doesn't deserve this' — that tells me how much she matters to me. That's not an awful person. That's someone who cares deeply.\"","e":"Reframes 'doesn't deserve' as care, not a self-sentence."},{"t":"\"I'm not awful — I was exhausted and lost control. Those are different things.\"","e":"Separates the act from identity."},{"t":"\"I need to learn to control my emotions. I'll sign up for therapy, start meditating.\"","e":"Action plan. Skips contact with the feeling, immediately switches to fixing.","inv":1}]},{"s":"Paige after her thesis defense: \"Got an A. Everyone's congratulating me, Mom's crying. And I'm thinking: the committee went easy. If they'd been stricter, I would've failed. Can't even feel happy. What's wrong with me?\"","o":[{"t":"\"Not being able to feel your own success — that's hard in itself.\"","e":"Names the secondary pain — the inability to feel the achievement."},{"t":"\"It'll pass with time. When you defend the next one, it'll be easier to own the result.\"","e":"Unsolicited optimism projected into the future. Dismisses current pain.","inv":1},{"t":"\"'What's wrong with me' — but nothing's wrong. You just haven't let yourself be enough in a very long time.\"","e":"Responds to the question gently, without a diagnosis."},{"t":"\"Everyone's congratulating you, but inside it's empty. That's its own kind of pain — when the celebration is there but you can't enter it.\"","e":"Names the gap between the external celebration and inner emptiness."}]},{"s":"Stas, living in Amsterdam: \"Here I'm 'the Russian.' Back home: 'You're not one of us anymore, Mr. European.' I don't belong anywhere. When I call Mom, she says 'we got snow here' — and I feel like a traitor. Don't even know who I betrayed. Probably everyone.\"","o":[{"t":"\"'Betrayed everyone' — that's incredibly heavy to carry. Especially when you can't even name who exactly.\"","e":"Acknowledges the guilt and its vagueness as a separate burden."},{"t":"\"You call Mom — and instead of closeness, it pulls you further apart. That's especially painful when she's the one you need warmth from.\"","e":"Names a specific moment of pain."},{"t":"\"That's normal for expats. The first couple of years are always like this. You'll find your crowd, and it'll get easier.\"","e":"Dismisses through 'happens to everyone.' Unsolicited optimism.","inv":1},{"t":"\"There you're Russian, here you're European — and everywhere, a little foreign. It's not that you don't fit in. It's just a very uncomfortable place.\"","e":"Acknowledges the split, lifts personal blame."}]},{"s":"Eva, late at night: \"Anxiety for no reason. Nothing happened, but everything inside is clenched. And it's frustrating that I can't explain it. 'What are you anxious about?' — 'I don't know.' Sounds stupid.\"","o":[{"t":"\"Anxiety without a reason is still anxiety. You don't owe anyone an explanation.\"","e":"Removes the demand to explain — causeless anxiety is still real."},{"t":"\"Probably something from the past. You should figure out the root causes — maybe see a therapist.\"","e":"Immediately searches for a cause and sends to a specialist. Eva didn't ask for help figuring it out.","inv":1},{"t":"\"The frustration of not being able to explain — that's its own thing. Anger at yourself for not understanding.\"","e":"Names the second layer — anger at self for not understanding."},{"t":"\"I feel bad and I don't know why. That doesn't mean I'm making it up.\"","e":"Acknowledges the state without justification."}]},{"s":"Adam: \"Laid off. Eight years there. The email came at nine, my access died while I was still reading it. HR said nothing personal, just restructuring. My mug is still in that office. And my sneakers under the desk. Friday I drove over to get it all, made it to my car with the box and broke down crying in the parking lot. First time in about fifteen years.\"","o":[{"t":"\"Eight years and they said goodbye with an automated email. That would have wrecked me.\"","e":"Acknowledges the mismatch, speaks for himself."},{"t":"\"Nothing personal, sure. Not personal for them. Your mug and your eight years are in that building.\"","e":"Picks up his own details, takes his side."},{"t":"\"It's for the best! Get some rest, and with your experience you'll land somewhere even better.\"","e":"Leaps over the loss and hands it a happy ending on the spot.","inv":1},{"t":"\"It isn't just the job you lost. The people, the routines, your whole weekday life.\"","e":"Notices there's more than one loss."}]},{"s":"Julia: \"My daughter is four months old. I love her, I really do. But my husband leaves at eight and gets back at seven, and my friends have basically gone extinct. On Thursday the delivery guy said have a nice day, and it flattened me so hard I stood in my building hallway with the grocery bag for ten minutes and couldn't make myself go inside. All because a stranger wished me a nice day.\"","o":[{"t":"\"Enjoy it! They grow so fast, you'll miss this time later.\"","e":"Answers loneliness with a demand for joy. Complaining gets even more shameful after that.","inv":1},{"t":"\"A whole day with a baby and not a single adult around. No wonder the delivery guy got to you.\"","e":"Ties it to the real cause, no panic, no verdicts."},{"t":"\"Ten minutes frozen in a hallway because a stranger was nice to you. How long has it been since you had an actual conversation.\"","e":"Sees the scale of the deficit behind the small thing."},{"t":"\"And where did your friends go while you're stuck here alone with a four month old. That stings.\"","e":"Notices the lost circle as its own thing."}]},{"s":"Keira: \"We dated for three months. I went to his friend's lake house, we talked about a vacation. A week ago he just stopped replying. Didn't block me, still reads my texts. On Wednesday I was up till three rereading our chat, looking for where I screwed up.\"","o":[{"t":"\"He reads and says nothing. Honestly that's rougher than a block: the hope resets every single time.\"","e":"Acknowledges what's torturous about this particular way of vanishing."},{"t":"\"Be thankful he bailed now and not two years in. He didn't deserve you, shake it off and move on.\"","e":"Cancels the right to grieve: it was lucky, after all.","inv":1},{"t":"\"You're up till three hunting for your mistake because he explained nothing. Your brain needs someone to blame, and it usually picks you.\"","e":"Shows where the self blame comes from."},{"t":"\"Those three months were real. The lake house, the plans. It's okay to miss it and be furious at him, both at once.\"","e":"Allows the contradictory feelings without choosing for her."}]},{"s":"Emma: \"I have an autoimmune condition. The labs are serious, but you'd never tell by looking at me. Inside it's like a flu that hasn't ended in four years. Last week a coworker went: I wish I had your disease, look at you, you're glowing. I smiled and went back to work. Then at home that evening I yelled at my daughter over an unwashed cup.\"","o":[{"t":"\"Being sick and having to prove you're sick on top of it. That's two full time jobs.\"","e":"Names the second load that invisibility adds."},{"t":"\"Glowing. Meanwhile inside it's year four of the flu. And nobody sees it, that's the trap.\"","e":"Speaks the gap in her own words."},{"t":"\"Well, you do look great! And hey, some people live with cancer, yours is manageable.\"","e":"The same rosy, just politer. Plus a comparison that makes complaining awkward.","inv":1},{"t":"\"And you have to explain it to every new person from scratch. The explaining alone would wear me out.\"","e":"Notices the fatigue of proving it, joins her."}]},{"s":"Vera: \"Nat and I were friends since college, twenty years. We never fought. She just started replying every other day, then once a week, and my happy birthday in March got nothing. Half my life is tied to her, and asking what happened feels stupid at this point.\"","o":[{"t":"\"Twenty years, and it ended without a single event. You can't even tell what day to count it from.\"","e":"Acknowledges that grieving without a clear end point is harder."},{"t":"\"Half your life. That's a loss, a real one, even though nobody died and nobody fought.\"","e":"Gives the grief the status it's missing."},{"t":"\"And there's no one to ask, that's the worst part. You got left with all the questions.\"","e":"Names the loneliness and the unanswered questions."},{"t":"\"People outgrow each other, it's normal. Let her go with gratitude for the good years.\"","e":"Pretty words that close the subject. Let go is a command, not sympathy.","inv":1}]}]},{"id":"vs_indulgence","tt":"Validation or Indulgence","ds":"Tell validation from indulgence","sm":"c","ins":["Read the situation","Pick validation — not indulgence","Indulgence supports action, not feeling"],"dt":[{"s":"Ian: \"Bombed the presentation. Voice shaking, forgot half of it. Everyone saw. A colleague texted 'it happens' — I want to reply something that'll shut him up.\"","o":[{"t":"Failing when everyone is watching — that's its own kind of pain. Not just a mistake.","e":"Acknowledges the pain of public failure. Doesn't touch the action.","ok":1},{"t":"Text him back — he had no business trying to comfort you.","e":"Supports the action."},{"t":"Exactly — let him know he shouldn't have butted in.","e":"Supports the anger and the action."}]},{"s":"Stella: \"Mom's been sick for three years. I dropped everything, moved in. Today she said I'm not doing enough. I want to leave and not answer her calls for a week.\"","o":[{"t":"Go — you deserve a break.","e":"Supports leaving as a decision, doesn't acknowledge the pain."},{"t":"Three years of giving everything — and hearing it's not enough. That's really painful.","e":"Acknowledges the injustice and the pain. Doesn't touch the action.","ok":1},{"t":"Exactly — let her be alone for a while, she'll understand.","e":"Supports the action and adds a revenge motive."}]},{"s":"Nikki: \"My friend lost her job — everyone's rallying around her. I've been depressed for six months and nobody asks. I want to text our mutual friends that I'm struggling too.\"","o":[{"t":"Text them — you absolutely have the right, you deserve attention too.","e":"Supports the action and amplifies it."},{"t":"Write to them — people just don't notice, you have to speak up.","e":"Supports the action with justification."},{"t":"Six months of struggling — and being invisible on top of it. That hurts.","e":"Acknowledges the pain of invisibility. Doesn't touch the action.","ok":1}]},{"s":"Andrew: \"My ex posted a photo with her new guy — traveling, laughing. We broke up six months ago. I want to like it — so she sees I still care.\"","o":[{"t":"Seeing her happy when you're hurting — that's hard.","e":"Acknowledges the pain. Doesn't touch the action.","ok":1},{"t":"Like it — let her know you're watching and you remember.","e":"Supports the action and adds a hidden motive."},{"t":"Go ahead and like it — what's the big deal, it's just a like.","e":"Supports the action by minimizing it."}]},{"s":"Marina: \"Everyone comes to me with their problems. My friend calls in tears again — an hour on the phone. I don't want to pick up — I want to turn my phone off for a week.\"","o":[{"t":"Good — let her find someone else.","e":"Supports withdrawal."},{"t":"Don't answer — you're not obligated to always be available.","e":"Supports the action through rights."},{"t":"Always being the one everyone leans on — that's exhausting.","e":"Acknowledges the exhaustion from the role. Doesn't touch the action.","ok":1}]},{"s":"Paul: \"After the layoff my ex boss posted on LinkedIn about restructuring with care for our people. Two hundred likes. I want to comment under that post and describe what the care looked like from the inside. I'm itching to hit send.\"","o":[{"t":"You got laid off by email and he's collecting likes for care. I'd be shaking too.","e":"Shares the anger. Stays out of the post.","ok":1},{"t":"Write it. People should know how it actually went.","e":"Pushes toward the action under the flag of truth."},{"t":"High time somebody called out guys like him. And doing it publicly is the right call.","e":"Approves both the action and the revenge."}]},{"s":"Roxanne: \"My first husband cheated for two years and I honestly saw nothing. Things are good now, he's a solid guy. But on Saturday he went to shower, left his phone in the kitchen, and I sat next to it until the water stopped. I'll look once and calm down, I know myself.\"","o":[{"t":"Look once and close the subject. The worst thing is winding yourself up for months.","e":"Promises calm through checking."},{"t":"You were cheated on for two years right under your nose. No wonder a phone left on the kitchen table sets off every alarm you have now.","e":"Explains the fear through her history. Leaves the phone alone.","ok":1},{"t":"After that you've earned the right to check. If he doesn't like it, let him prove he's clean.","e":"Frames checking as a right and hands the new partner the bill."}]},{"s":"Laura: \"My mother in law in the family chat again: the kid is so skinny, well what do you expect, mommy doesn't like cooking. With a smiley. Third time this month. My husband says nothing, his sister reacts with a laughing emoji. I've already typed a reply, finger over the send button.\"","o":[{"t":"Reply right there, in front of everyone. She went public, you go public, fair is fair.","e":"Green lights answering in kind, since she started it."},{"t":"Time to shut her down once and for all. Otherwise she'll keep riding you.","e":"Nudges her on and adds urgency: it'll only get worse."},{"t":"Third time in front of the whole family. Your husband silent, his sister laughing along. At this point it isn't even about her: nobody had your back.","e":"Notices the main wound, her own people doing nothing. Leaves the button alone.","ok":1}]},{"s":"Kyle: \"My boss spent twenty minutes at the meeting taking my project apart. Kindergarten work, embarrassing to show a client. In front of everyone. I sat there nodding. I've just opened a doc with my resignation letter. Screw the mortgage, I'm not going in tomorrow.\"","o":[{"t":"Twenty minutes in front of everyone, and you sat there nodding. I'd have that doc open too.","e":"Acknowledges the humiliation and the urge. Doesn't bless the letter.","ok":1},{"t":"Send it. Your health and self respect are worth more than a mortgage.","e":"Blesses the action with a value, pushes the mortgage aside."},{"t":"Good, and slam the door loud. That's the only way guys like him learn.","e":"Goes along with quitting and adds a motive: teach him a lesson."}]},{"s":"Maya: \"Third year of IVF, the second failed round was in May. On Sunday Lena sent me an ultrasound photo: soon there will be three of us!!! I wrote yay, congrats, and turned my phone off till morning. I want to hide her stories and not talk for a month or two. I do that with every pregnant friend now, there's a whole list.\"","o":[{"t":"Hide her and don't talk. You don't owe anyone a front row seat to their pregnancy.","e":"Backs the avoidance by calling it self care."},{"t":"You wrote yay and shut the phone off till morning. Three years of trying, of course someone else's ultrasound hits like a slap. And you really are glad for Lena, that comes through too.","e":"Acknowledges both sides and the cost behind them. Leaves the list alone.","ok":1},{"t":"Honestly, a friend could think twice before sending you an ultrasound. So it's only fair.","e":"Approves and appoints the guilty party."}]}],"cn":"Indulgence is when we support an action or decision instead of acknowledging the feeling. Validation says 'you're in pain' — indulgence says 'you're right, do it.' The difference is huge: validation helps a person rely on themselves, while indulgence amplifies the impulse and prevents them from figuring things out."},{"id":"layers","tt":"Different Layers","ds":"Mark all validating layers","sm":"m","ins":["Read the situation","Mark all layers that accurately validate","Two out of five are off — three are spot on"],"dt":[{"s":"Ryan: \"Got promoted. Everyone's congratulating me. Waiting for them to say it was a mistake. Max works harder, Lena is smarter. I just got lucky.\"","o":[{"t":"Agonizing anticipation of being exposed","e":"\"Waiting for them to say it was a mistake\" — the core experience. Named directly.","v":1},{"t":"Exhaustion from an inner voice that has been talking for a long time","e":"\"Max is better, Lena is smarter\" — not a fresh thought. That voice has been running for a while.","v":1},{"t":"Fear of letting down the people who promoted him","e":"Different angle. Ryan isn't afraid of disappointing management — he's afraid of being exposed."},{"t":"Loneliness in anxiety while everyone celebrates","e":"The contrast between the celebration outside and the fear inside. He's alone in this.","v":1},{"t":"Resentment that achievement doesn't bring joy","e":"Ryan doesn't mention lack of joy. He talks about fear. Attributes a feeling that isn't there."}]},{"s":"Tim: \"Max posted about his first million. I know it's all lies — debt, wife left. But everyone likes it. And I'm jealous. Even though I know the truth.\"","o":[{"t":"The contradiction between knowing and feeling","e":"\"I know it's lies... and I'm jealous\" — the mind knows one thing, the feeling does another.","v":1},{"t":"Shame for envying what you yourself know is fake","e":"Tim isn't ashamed. He says 'I'm jealous' openly. Attributing shame."},{"t":"Powerlessness — you see the truth and can't prove anything","e":"\"Everyone likes it\" — he knows the truth, but nobody cares. Powerlessness against the image.","v":1},{"t":"Loneliness — knowing what others don't and staying silent","e":"He's alone with this knowledge. Everyone likes it, nobody sees what he sees.","v":1},{"t":"Anger at people who fall for the image","e":"Tim isn't angry at the likers. He's talking about himself, his own envy."}]},{"s":"Caleb: \"I want music. Dad: 'do what you want, but don't come complaining later.' Mom's silent. I don't know — is this support or a threat?\"","o":[{"t":"The trap inside the permission","e":"'Do what you want, but don't complain' — technically permission, actually a threat.","v":1},{"t":"Mom's silence as a separate blow","e":"Mom is silent — and that's not neutrality. Caleb singles it out — it hurts separately.","v":1},{"t":"Fear that if it doesn't work out, there'll be no help","e":"Caleb isn't worried about future failure. He's about right now: can't decode the message."},{"t":"Confusion — doesn't know whether to celebrate or be afraid","e":"'I don't know — is this support or a threat' — literally his words.","v":1},{"t":"Feeling that his dream isn't taken seriously","e":"Caleb came with confusion about the double message, not resentment about his dream."}]},{"s":"Lisa: \"Spent three hours listening to Kate's problems. Then my turn — 'oh gotta run, let's catch up.' Never called back. I'm angry — but it's not her fault, she's just like that.\"","o":[{"t":"Imbalance","e":"Three hours listening — not listened to. Unequal distribution of attention — a fact that hurts.","v":1},{"t":"Disappointment in closeness that turned out to be one-sided","e":"Lisa doesn't generalize to the relationship level. She's angry about a specific episode. Over-interpreting."},{"t":"Self-ban on anger","e":"'I'm angry — but it's not her fault' — classic self-prohibition. Lisa is angry and immediately revokes her right to be.","v":1},{"t":"Exhaustion from the pattern repeating","e":"'Never called back' — this isn't the first time. Exhaustion from repetition.","v":1},{"t":"Sadness about having to choose between friendship and her boundaries","e":"Lisa isn't facing a choice about boundaries. She's angry and forbidding herself. Attributes reflection she doesn't have yet."}]},{"s":"Philip: \"Nothing happened. I just think every day — something's off. I don't tell my wife. She'll say 'you're tired, take a rest.'\"","o":[{"t":"No reason — and that makes it even harder","e":"The absence of a cause doesn't lighten it — it intensifies it. No way to explain your own state to yourself.","v":1},{"t":"Fear that this is the start of something serious","e":"Philip doesn't mention fearing a diagnosis. He talks about carrying it alone. Over-interpreting."},{"t":"Loneliness — silent because he knows they won't understand","e":"'I don't tell my wife' — he already knows the reaction. Forced loneliness.","v":1},{"t":"Quiet daily pain — not acute, but no lighter","e":"'Every day' — chronic, background pain. Precise naming of the character of his state.","v":1},{"t":"Irritation that loved ones will reduce it all to tiredness","e":"Philip isn't irritated. He knows the reaction in advance and stays silent. Not anger — tired acceptance."}]},{"s":"Tamara: \"I visited Mom. She looked at me and asked: are you from social services? Then she recognized me and laughed: silly old me. I stayed, we had tea, and at home I told everyone the visit went fine. Then I sat in the car outside for about forty minutes, couldn't turn the key.\"","o":[{"t":"Losing Mom while she's alive","e":"Mom is right there, but the recognizing is going piece by piece. This grief started long before any funeral.","v":1},{"t":"Holding it together until the car","e":"Tea, the visit went fine, forty minutes in a car she never started. That's what fine costs.","v":1},{"t":"Anger at Mom","e":"There's no anger in her story. There's tea, fine, and forty minutes in the car. Attributed."},{"t":"Alone with it","e":"The family got went fine. Which means falling apart is allowed only in the car, and nobody knows how it actually is for her.","v":1},{"t":"Guilt about not doing enough for Mom","e":"Not a word about not enough or should do more. Invented."}]},{"s":"Dennis: \"My son is fifteen. I ask how school was — fine. How are things — fine. And the door closes. Three years ago we spent a month building a Lego starship, he told me about every single piece. He's home, technically. And I miss him like he moved away.\"","o":[{"t":"Missing someone who is home","e":"I miss him like he moved away — his own words. His son is behind the wall and there's no way through.","v":1},{"t":"Grieving that version of them","e":"The starship and the stories about every piece. That's what the ache is for: that format is gone.","v":1},{"t":"Resentment over ingratitude","e":"There's no after all I've done for him here. It's longing, there's no tab. Attributed."},{"t":"Powerlessness","e":"The door closes and you can't open it from outside. You can't force a conversation, only wait.","v":1},{"t":"Fear of a bad crowd","e":"Not a word about friends or worry for his safety. Invented."}]},{"s":"Victor: \"Two credit cards maxed out, eighth month of shuffling the balance between them. At work I crack jokes, at home it's all under control, don't worry. On Sunday my wife was showing me hotels for the May holidays, I said yeah, looks nice, while doing minimum payment math in my head.\"","o":[{"t":"Fear that never switches off","e":"He's doing the minimum payment math during a vacation chat. The anxiety has no off button.","v":1},{"t":"Living on two fronts","e":"Jokes at work, under control at home, and the truth only in his head. That alone is draining.","v":1},{"t":"Loneliness right next to his wife","e":"She's picking a hotel, he's beside her doing payment math. Can't get closer, and can't say a word.","v":1},{"t":"Anger at the banks","e":"There are no banks in his story. There's fear and silence. Attributed."},{"t":"Regret about the purchases","e":"He doesn't say where the debt came from and doesn't flog himself over the past. Invented."}]},{"s":"Linda: \"My daughter got into a university in another city, and I'm the one who talked her into going. We saw her off in August. Now I wander into her room for no reason, there are a third fewer dishes to wash, and the apartment is so quiet I can hear the fridge. She's loving it there, calls all happy. And I don't tell her that I sometimes sit on her bed for no reason. It feels awkward: she's doing great.\"","o":[{"t":"Pride and emptiness at the same time","e":"She talked her into going, the daughter is happy. And there's a third less dishes. Both facts are real, neither cancels the other.","v":1},{"t":"A ban on her own sadness","e":"I don't tell her, it feels awkward. The sadness is under lock, because the daughter is doing great.","v":1},{"t":"Resentment at her daughter","e":"She talked her into it herself. There's no resentment in the story. Attributed."},{"t":"Silence you can hear","e":"The fridge became audible. The emptiness in the house literally has a sound now.","v":1},{"t":"Fear of being unneeded","e":"She doesn't say she isn't needed anymore. She talks about the quiet and feeling awkward about her own sadness. Invented."}]}],"cn":"In one situation, a person can feel several things at once: hurt, shame, loneliness, fear. Each is a separate layer. Good validation sees not one feeling but several. Your task is to mark the layers that accurately describe the experience — and leave out the ones that attribute something that isn't there."},{"id":"meta","tt":"Meta Level","ds":"Which approach works here","sm":"c","ins":["Read the situation","Choose the approach that fits best here","Think 'how to approach,' not 'what to say'"],"dt":[{"s":"Cara, quietly: \"Whiskers died yesterday. 14 years together. At work everyone says: 'It's just a cat, get a new one.' As if she were a thing.\"","o":[{"t":"Name the irreversibility","e":"14 years — not 'just a cat.' Acknowledge the scale of the loss without trying to fix it.","g":"Works","ok":1},{"t":"Lift shame for the feeling","e":"No shame here — Cara isn't embarrassed about her pain. The issue is the dismissal.","g":"Close"},{"t":"Name the feeling","e":"A first step. But what matters more here is acknowledging what was lost.","g":"Surface level"},{"t":"Offer connection","e":"Connection matters, but first — acknowledge the scale of the loss.","g":"Not a fit"}],"m":"In grief theory (Worden) the first task is to acknowledge the reality of the loss. When others dismiss the loss ('get a new one'), grieving is blocked — the person loses the right to their own pain. 'Name the irreversibility' restores the weight of the loss and opens the possibility to grieve.","ex":"\"14 years — that's a huge part of your life. Of course the pain of this loss runs deep.\""},{"s":"Greg: \"Panic attacks. Heart pounding, hands shaking, feels like I'm dying. Told my mom — she said: 'It's from your phone, go take a walk.' Friends: 'You think too much.' Like I'm making it up.\"","o":[{"t":"Remove the demand to explain","e":"Greg isn't complaining about having to explain — he's complaining that nobody believes him.","g":"Wrong context"},{"t":"Name isolation as a separate layer","e":"Isolation is there, but first it's more important to acknowledge the experience itself.","g":"Second layer"},{"t":"Acknowledge the body signal","e":"Heart, hands, feeling of dying — the body doesn't lie. Acknowledge the physical experience as real.","g":"Works","ok":1},{"t":"Name the double blow","e":"Double blow is there: panic + 'you're making it up.' But first acknowledge the bodily experience.","g":"Close"}],"m":"During panic attacks the body generates a mortal threat signal — sympathetic nervous system activation, adrenaline release. When others say 'you're making it up,' it's gaslighting of bodily experience. In somatic experiencing (Levine) acknowledging bodily sensations (tracking) is the first step toward regulation.","ex":"\"What you're describing — heart, hands, feeling like you're dying — that's terrifying to go through.\""},{"s":"Nadia, quietly: \"Miscarriage. 8 weeks. We hadn't told anyone yet. So now I'm grieving, and it's a regular day for everyone else. A friend said: 'Well, 8 weeks — that's not really a baby yet.' Then I cried in the bathroom for an hour.\"","o":[{"t":"Lift shame for the feeling","e":"Shame may be there, but the central wound is different: the right to grieve is being denied.","g":"Not central"},{"t":"Name the loss directly","e":"Without numbers, without conditions. Name the loss — give grief the right to exist.","g":"Works","ok":1},{"t":"Acknowledge isolation as a separate layer","e":"Isolation is there, but without acknowledging the loss itself, naming isolation has no foundation.","g":"Second layer"},{"t":"Name the irreversibility","e":"Irreversibility is about scale. Here it's deeper: the very right to grieve is being denied.","g":"Close"}],"m":"This is 'disenfranchised grief' (Doka) — a loss that society doesn't grant the right to grieve. '8 weeks — not really a baby' denies the legitimacy of the loss. The person loses not only what they lost, but also the ability to grieve it. Naming the loss directly gives grief the right to exist.","ex":"\"You lost a baby. Not '8 weeks.' A baby. Grieving is your right.\""},{"s":"Erin: \"I told Josh it hurt that he didn't call when I was sick. And he said: 'You're being dramatic again. I was busy. Stop making a scene.'\"","o":[{"t":"Name the feeling","e":"'You're hurt' — true, but doesn't reflect that two blows happened in a row.","g":"Surface level"},{"t":"Rename the trap","e":"Erin isn't stuck in his word — she's outraged by it.","g":"Wrong context"},{"t":"Name the double blow","e":"Didn't call — first blow. Called her pain 'a scene' — second. Name both layers.","g":"Works","ok":1},{"t":"Acknowledge guilt without denying it","e":"Erin doesn't feel guilty. She's hurt and dismissed.","g":"No guilt"}],"m":"Double blow — when the reaction to pain causes a second pain. In EFT (Sue Johnson) this is 'protest behavior of attachment': Erin signals she needs connection, and receives dismissal in return. The second blow is more dangerous: it teaches that speaking about pain is unsafe.","ex":"\"Wait — you came to say it hurt, and he called it 'a scene'? That's a double blow — first he didn't call, then he dismissed you on top of it.\""},{"s":"Tanya: \"Grandma is in the hospital. Mom goes every day, but I can't. Work, kids, no energy. Grandma says: 'It's fine, don't come.' But I know she's struggling. And I know I'll regret it later.\"","o":[{"t":"Acknowledge both pulls","e":"'Both pulls' — when two desires pull in opposite directions. Tanya doesn't have two equal desires — she has a choice that can't be made without losing something.","g":"Close"},{"t":"Name the trap","e":"Go — no energy. Don't go — guilt will eat you alive. Naming the trap is more honest than looking for a way out.","g":"Works","ok":1},{"t":"Acknowledge guilt without denying it","e":"Acknowledging guilt matters, but without naming the trap, it sounds like agreeing with it.","g":"Premature"},{"t":"Remove the demand to explain","e":"Tanya isn't complaining about having to explain. She's complaining there's no good option.","g":"Wrong context"}],"m":"This is a 'double bind' (Bateson) — a situation where any choice leads to loss. Unlike a dilemma where a better option exists, a double bind has none. Trying to find the 'right answer' intensifies suffering. Naming the trap removes the demand to solve the unsolvable.","ex":"\"Go — no energy. Don't go — guilt eats you alive. Neither option is good.\""},{"s":"Jen, in a whisper: \"Every kid in my daughter's class has an iPhone. She asked. We can't afford it. I bought an Android. She said 'thanks,' but I saw how disappointed she was. I feel like a bad mom.\"","o":[{"t":"Name the feeling","e":"Jen already named what she feels. Repeating adds nothing.","g":"Surface level"},{"t":"Lift shame for the feeling","e":"Jen doesn't have shame for a feeling — she has guilt about a situation. Different emotions.","g":"Wrong mechanism"},{"t":"Redirect to the real wound","e":"Redirecting is accurate but premature. First acknowledge the guilt itself.","g":"Second step"},{"t":"Acknowledge guilt without denying it","e":"'You're not a bad mom' too soon is invalidation. First acknowledge that the guilt exists and that it's heavy.","g":"Works","ok":1}],"m":"In DBT (Linehan) this is level 3 validation — acknowledging the unspoken. Jen says 'bad mom' — behind it is guilt. The reflex is to deny: 'No, you're a good mom!' But denial before acknowledgment = invalidation. The person hears: 'your feeling is wrong.'","ex":"\"'I feel like a bad mom' — that's so heavy to carry. Especially when you're doing everything you can.\""},{"s":"Alina, to a friend: \"I'm always the one who reaches out. I text, ask how they're doing, show up when things are bad. Last week I had a rough day — messaged both friends. Both read it. One replied a day later. The other never replied at all.\"","o":[{"t":"Name isolation as a separate layer","e":"Isolation is there. But first it's more important to reflect the imbalance.","g":"Second layer"},{"t":"Echo with surprise","e":"Echo reacts to the fact. Contrast is more precise: it shows the structure of the imbalance.","g":"Close"},{"t":"Name the contrast without a verdict","e":"Reflect the imbalance — don't draw the conclusion for her. The contrast speaks for itself.","g":"Works","ok":1},{"t":"Name the double blow","e":"Double blow is when the reaction to pain causes a second pain. Here it's a chronic imbalance.","g":"Wrong structure"}],"m":"In motivational interviewing (Miller & Rollnick) there's a principle: don't give the conclusion, create conditions for the person to reach it themselves. Reflecting the contrast is more powerful than any external verdict — it doesn't trigger resistance.","ex":"\"You show up when they need you. And they don't even reply. The difference is hard to miss.\""},{"s":"Ryan: \"Got promoted. Everyone's congratulating me, but I'm waiting for them to say it was a mistake. Max works harder, Lena is smarter. I just got lucky. Or management messed up.\"","o":[{"t":"Name the secondary pain","e":"Secondary pain is pain from your reaction to pain. Ryan's pain is primary — the fear of being exposed.","g":"Wrong emotion"},{"t":"Echo with surprise","e":"Repeat his words with genuine surprise — don't explain, don't treat. Add one word: how it feels.","g":"Works","ok":1},{"t":"Don't argue with the inner voice","e":"A precise method for impostor syndrome. But echo comes first — it names what it's like to live with that voice.","g":"Next step"},{"t":"Lift shame for the feeling","e":"Ryan isn't ashamed of his anxiety — he's afraid of being exposed. Different experiences.","g":"Wrong mechanism"}],"m":"Echo with surprise is a form of accurate empathic reflection (Rogers) with a live emotional response. In impostor syndrome (Clance & Imes) the person doesn't feel the absurdity of their position from inside. Echo returns an outside perspective without arguing: not 'you're wrong' but 'listen to how that sounds.'","ex":"\"Promoted — and you're sitting there waiting for them to say 'oops, our bad'? Ryan, that's excruciating.\""},{"s":"Eva, late at night: \"Anxiety for no reason. Nothing happened, but everything inside is clenched. And it's frustrating that I can't explain it. 'What are you anxious about?' — 'I don't know.' Sounds stupid.\"","o":[{"t":"Name the feeling","e":"Eva already knows she feels anxiety. The problem isn't the name.","g":"Surface level"},{"t":"Acknowledge the split as normal","e":"Eva doesn't have a split — no two conflicting feelings. One feeling and the inability to explain it.","g":"Wrong context"},{"t":"Remove the demand to explain","e":"'What are you anxious about?' is a cognitive demand during a crisis. Removing the need to justify is already validation.","g":"Works","ok":1},{"t":"Lift shame for the feeling","e":"Shame is there — 'sounds stupid.' But it's specifically about not being able to explain. Removing the demand is more precise.","g":"Close"}],"m":"Anxiety often has no cognitive content — it's nervous system activation without a clear trigger. The question 'what about?' assumes that an emotion must have a cause. In DBT (Linehan) acknowledging the experience without explanation removes the cognitive filter and gives the emotion the right to exist.","ex":"\"Feeling bad and not knowing why doesn't mean you're making it up. Anxiety without a reason is still anxiety.\""},{"s":"Josh after a fight: \"Lost it again over nothing. My wife just asked about dinner and I started yelling. What an awful person I am. She doesn't deserve this.\"","o":[{"t":"Separate the act from identity","e":"'Snapped' is an action. 'Awful person' is a verdict. Separating them opens space for reflection.","g":"Works","ok":1},{"t":"Lift shame for the feeling","e":"Josh doesn't have shame for a feeling — he has a label on himself as a person. Different processes.","g":"Wrong mechanism"},{"t":"Name both feelings at once","e":"Two feelings are there. But the central problem is that he's fused the act with who he is.","g":"Not central"},{"t":"Name the feeling","e":"Josh already knows what he feels. He needs the separation of action and identity.","g":"Surface level"}],"m":"In cognitive therapy (Beck) this is working with a global negative label — the cognitive error of overgeneralization: 'I snapped' → 'I'm awful.' While the act is fused with identity, reflection is impossible: the person doesn't analyze what happened, but punishes themselves for who they are.","ex":"\"I'm not awful — I was exhausted and lost control. Those are different things.\""},{"s":"Roman: \"We buried my father on Tuesday. My phone won't stop: stay strong, hang in there, call if you need anything. I look at these messages and don't know what to reply. Yesterday my brother came over and we sat in the kitchen for three hours, mostly silent. First time all week it got a little easier.\"","o":[{"t":"Stay present without words","e":"He says himself what helped: three hours in the kitchen, mostly silent. His brother already demonstrated the method, just repeat it.","ok":1},{"t":"Name the feeling","e":"That he's in pain is visible as is. Naming it out loud means demanding conversation again, and conversation is what's suffocating him."},{"t":"Offer concrete help","e":"He has read call if you need anything twenty times already. Errands can wait. The request right now is different: someone around."},{"t":"Name the irreversibility","e":"That's a verbal method, and words aren't landing right now. Fine tool, wrong moment."}],"m":"Linehan's first level of validation is presence: being there and listening, fixing nothing. Alan Wolfelt, who teaches grief companionship, calls it companioning: walking next to a person in their grief instead of leading them somewhere. Silence together often helps more than words, because it asks nothing back, not even an answer.","ex":"\"I'll drop by Saturday. I can just sit with you, we don't have to talk.\""},{"s":"Chris, after his divorce, invites you over to sort out the apartment: \"Take the coffee machine, what do I need all this stuff for on my own. It's all fine, honestly, I even feel relieved. Come on, to the new life.\" It's the third toast to the new life. The coffee machine he and his wife spent six months choosing, he shoves into your hands along with the box.","o":[{"t":"Name the unspoken — gently","e":"A third toast, and the machine they chose together for six months pushed into your hands. You can say it quietly and once: if there's anything under fine, I'm here. And not press.","ok":1},{"t":"Support the optimism","e":"I even feel relieved is a defense. Playing along leaves him alone behind it."},{"t":"Echo with surprise","e":"Echo returns what was said, and what was said is fine. You would just be nodding at the front."},{"t":"Ask point blank: are you hurting?","e":"Point blank forces a confession or a lie. The lie is likelier, and the door closes."}],"m":"Linehan's level 3 is voicing what the person feels but doesn't say. Delivery decides everything here: not a diagnosis (you're clearly hurting) but an open door (when you want to tell it like it's, I'm here). Without the right to stay silent, this method turns into prying someone's armor open.","ex":"\"I'll take the machine. And listen, if you ever feel like telling me the real version instead of fine, say the word any time. Okay, pour.\""},{"s":"Jane: \"My new boyfriend was two hours late on Friday, phone died. In those two hours I managed to live through everything: him lying, me noticing nothing again, me packing boxes. He showed up with flowers and couldn't understand why I wouldn't talk to him. I know it's about my ex. I know. And I'm still shaking.\"","o":[{"t":"Validate through her history","e":"She doesn't need the situation explained, she took it apart herself. She needs to hear: after two years of lies, this shaking is memory doing its expected job.","ok":1},{"t":"Name the feeling","e":"She names everything herself, precisely. Naming it again adds nothing."},{"t":"Separate the act from identity","e":"That method is for people flogging themselves over something they did. Jane did nothing, she spent two hours afraid."},{"t":"Remove the demand to explain","e":"Nobody is demanding explanations. She volunteers them first."}],"m":"Linehan's level 4: showing that the feeling follows logically from the person's history. A reaction that looks oversized for the situation is usually exactly the size of past experience. When given what you lived through, this is expected gets said out loud, the second pain goes: the shame about one's own reaction.","ex":"\"You were lied to for two years and found out last. Of course two hours of silence starts the whole old movie in your head. That's how memory is built.\""},{"s":"Christina, in a whisper while the kids are in the bath: \"On Saturday they screamed in a duet for almost an hour, and I caught myself picturing it: I walk out, get in the car, and drive. No bags, no plan. Just drive. Then the younger one hugged me with wet hands and I felt so ashamed about that car that I lay awake half the night replaying it.\"","o":[{"t":"Normalize as universally human","e":"An escape fantasy after an hour of screaming is a standard reaction of an overheated mind. Once she hears this happens to everyone at their limit, the bad mother label starts peeling off.","ok":1},{"t":"Validate through her history","e":"Works when the feeling grows out of personal past. The past isn't the driver here, an hour of screaming is."},{"t":"Name the double blow","e":"The second blow she deals herself, with shame. Normalizing is exactly what removes it."},{"t":"Offer connection","e":"A hug is fine. But am I normal isn't answered by a hug."}],"m":"Linehan's level 5 is normalizing: anyone in your place would feel this. It lifts shame over feelings a person considers forbidden. What gets normalized is the feeling and the fantasy, actions aren't in question. And it isn't a brush off (everyone is like that, relax): the weight the feeling grew out of gets acknowledged separately.","ex":"\"An hour of stereo screaming — any living person is mentally on the highway already. You didn't drive anywhere, you finished their bath. There's your answer about what kind of mother you're.\""},{"s":"Arthur has lymphoma, he's in treatment, the prognosis is decent. \"You know what's worse than chemo? Everyone talks to me like a planetarium narrator now. Slow, careful. My best friend spent half an hour the other day working up to tell me his car broke down. Didn't want to burden me. I have cancer, not glass bones.\"","o":[{"t":"Talk to him as an equal","e":"He said it himself: cancer, not glass. Ordinary news, ordinary complaints, ordinary teasing. That's how he stays a person and not a diagnosis.","ok":1},{"t":"Name the feeling","e":"Possible, but you risk doing it in that same narrator voice. He's asking for the old tone, not for words about himself."},{"t":"Acknowledge the body signal","e":"He isn't talking about his body. He's talking about how people talk to him."},{"t":"Lift shame for the feeling","e":"There's no shame in his words. There's anger at the planetarium around him."}],"m":"Linehan's level 6 is radical genuineness: carrying yourself with the person as an equal, no special protective mode. The careful tone he never asked for tells him every time that he's different now. Ordinary treatment, car complaints included, puts him back among the living.","ex":"\"Listen, my boiler is leaking and I'm about to dump the whole saga on you, brace yourself. And chess on Saturday, you promised a rematch. Illness isn't an excuse.\""},{"s":"Dina, six months pregnant: \"We wanted this for three years. And I lie there at night staring at the ceiling thinking: what if I can't love her? Everyone around me is glowing, asking if I'm happy. I say of course. Once I typed why do I feel nothing about being pregnant into Google, and deleted it like I'd been googling a crime.\"","o":[{"t":"Acknowledge the split as normal","e":"Three years of wanting, and ceiling staring fear. She needs to hear both facts are real and neither cancels the other. Then of course stops being a lie to herself.","ok":1},{"t":"Normalize as universally human","e":"A neighboring method, but everyone gets scared smears her specific knot: expecting, and at the same time not feeling what she's supposedly meant to."},{"t":"Name the feeling","e":"There are two, pulling opposite ways. Naming one means playing along with half."},{"t":"Remove the demand to explain","e":"There are no outside demands, the of course is her own. This is about the right to the second feeling, not about reporting."}],"m":"Opposite feelings at the same time about something important is how minds normally work. The dialectical approach (it's the D in DBT) doesn't force a choice between feelings: both get acknowledged at once, I want this and I'm afraid. The demand to pick one correct feeling is what manufactures something is wrong with me.","ex":"\"You have waited three years for her, and you're scared. People work like this all the time, one doesn't cancel the other. And you can google that query in peace, nobody goes to jail for it.\""},{"s":"Nick: \"Missed my residency exam by four points. For six months I lived by a six a.m. alarm, unsubscribed from everything, didn't see friends. I called my dad, he heard me out and said: guess you didn't study hard enough. I hung up and I'm just sitting here. What if he's right? What if I really could have done more?\"","o":[{"t":"Acknowledge the effort, not the outcome","e":"His dad's line erased six months of alarms with one word. Until someone puts those six months back, what if he's right keeps corroding.","ok":1},{"t":"Echo with surprise","e":"Echo would expose how wild the line is, but Nick is already half on his dad's side. Restore the facts first."},{"t":"Separate the act from identity","e":"He isn't blaming himself for an act. He's doubting whether his six months count."},{"t":"Name the double blow","e":"The blow is double, true. But that's a description. What if I could have done more is answered by acknowledging what was done."}],"m":"Carol Dweck showed with schoolkids: when only the result gets judged, one failure crosses out the whole process, and the person stops seeing their own work. Acknowledging effort puts the erased facts back: six months of six a.m. happened, and four points don't undo them.","ex":"\"Hold on. Six months of six a.m. alarms — happened. Giving everything up — happened. Four points is about the exam. It says nothing about how you prepared.\""},{"s":"Steve: \"A coworker's mom died a month ago. The whole department chipped in, I covered her shifts. Meanwhile my divorce is underway, I'm sleeping about three hours a night, and at lunch I sit in my car so I don't have to talk to anyone. I can't tell anybody. Her mother died, and I'm supposed to come crawling with my divorce? I'm ashamed to even compare.\"","o":[{"t":"Remove the hierarchy of pain","e":"He crossed himself off the sympathy list: ashamed to even compare. As long as pain queues up by severity, three hours of sleep stays nothing.","ok":1},{"t":"Name the feeling","e":"He knows he's hurting. What's stuck is I've no right. The right is what needs the work."},{"t":"Normalize as universally human","e":"People survive worse is the normalization he's numbing himself with. Risk of pouring more of the same."},{"t":"Acknowledge isolation as a separate layer","e":"Lunch in the car is isolation, yes. But it follows from the ban. Start with the cause."}],"m":"Brene Brown calls it comparative suffering: internal bookkeeping where compassion is owed only for a big enough tragedy. The books lie in both directions: your silence doesn't ease her grief. And yours grows in the quiet. There's enough compassion to go around, it doesn't need dividing.","ex":"\"She's grieving. And you're grieving. Compassion isn't a cake you have to split. Three hours of sleep for a month straight is serious. Come on, let's talk.\""}],"cn":"Here we train not 'what to say' but 'how to approach.' This is the strategy level: naming the feeling, lifting shame, acknowledging the scale of a loss, normalizing a reaction — these are different tools. The task is to pick the one that fits the situation most precisely."}]};
